insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('snow-day-stuck-at-home-plan-sheet', 'Snow Day Stuck at Home Plan Sheet', 'worksheet'::resource_kind, 'A plan for an unexpected day shut in by weather, for a client whose mood sinks when the routine is canceled.', 'Use it to give a client a shape for a day that arrives with no plan, so the hours do not all become screen time and dread.', array['Adults']::text[], '20 minutes, made before the season', 'A snow day, a storm closure or a canceled commute sounds like a gift and often lands as a low, aimless day for a client who leans on routine. Fill the sheet in before the weather does: three things that need daylight, one thing that needs other people (a call counts), one thing that needs hands, and the hour the client will step outside whatever the sky is doing. Keep the list short enough to finish. Watch for the client who fills the day with chores as penance; the sheet asks for one thing that is only for pleasure.', '[{"id": "f0", "type": "textarea", "label": "What usually happens to my day and my mood when the normal plan is canceled:"}, {"id": "f1", "type": "textarea", "label": "Three things I would do with daylight hours if I had them handed to me:"}, {"id": "f2", "type": "textarea", "label": "One person I would call or text on a shut-in day, and roughly when:"}, {"id": "f3", "type": "textarea", "label": "One thing that uses my hands (cooking, fixing, building, drawing):"}, {"id": "f4", "type": "textarea", "label": "The time I will step outside, even for five minutes, and what I will wear:"}, {"id": "f5", "type": "textarea", "label": "One thing on the list that is only for pleasure, not productivity:"}, {"id": "f6", "type": "textarea", "label": "After the day: what I actually did, and what I would keep for the next one:"}]'::jsonb, array['planning', 'routine', 'mood']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('medical-leave-return-first-week-pacing-sheet', 'Medical Leave Return First Week Pacing Sheet', 'worksheet'::resource_kind, 'A paced plan for the first week back at work after medical leave, covering energy, questions from coworkers and the backlog.', 'Use it to help a client return to work at a pace their body can keep, instead of trying to make up the lost weeks by Friday.', array['Adults']::text[], '30 minutes, the week before returning', 'The first week back after a medical leave usually goes wrong in one of two ways: the client overdoes it to prove they are fine, or spends the week braced for questions. The sheet plans both. For each day the client picks the hours they will work, the one task they will finish, and the break they will take whether or not they feel they need it. Then they write the one-sentence answer they will give to how are you feeling, and who at work knows enough to run interference. Review the sheet midweek if you can; the plan tends to slide by Wednesday.', '[{"id": "f0", "type": "textarea", "label": "My return date, and the hours I plan to work each day of the first week:"}, {"id": "f1", "type": "textarea", "label": "The one task I will finish each day, and the backlog items that can wait until week two:"}, {"id": "f2", "type": "textarea", "label": "The break I will take each day, and where I will take it:"}, {"id": "f3", "type": "textarea", "label": "My one-sentence answer when a coworker asks how I am feeling:"}, {"id": "f4", "type": "textarea", "label": "Who at work knows enough to help if I need to leave early:"}, {"id": "f5", "type": "textarea", "label": "The signs that I am overdoing it, and what I will do when I notice one:"}, {"id": "f6", "type": "textarea", "label": "End of the week: how it went, and what the second week should look like:"}]'::jsonb, array['pacing', 'work', 'energy']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('thanksgiving-hosting-hour-by-hour-plan-sheet', 'Thanksgiving Hosting Hour by Hour Plan Sheet', 'worksheet'::resource_kind, 'An hour by hour plan for a client hosting a holiday meal, with the help they will ask for and the moment they will sit down.', 'Use it to turn a day the client dreads into a sequence of hours, with help assigned before anyone arrives.', array['Adults']::text[], '30 minutes, a week before the day', 'Hosting a holiday meal piles logistics, family dynamics and a standard of perfection into one afternoon. The sheet breaks the day into hours from the first oven timer to the last dish, and for each hour the client writes what happens and who does it. Push on the who: most clients plan to do everything and resent everyone by dessert. The last lines ask for the minute the client will sit down with a plate and the one thing they will let be imperfect. Bring it back the week after and see what actually happened.', '[{"id": "f0", "type": "textarea", "label": "The hours of the day, from first task to last, and what happens in each:"}, {"id": "f1", "type": "textarea", "label": "The three jobs I will hand to someone else, and who I will ask this week:"}, {"id": "f2", "type": "textarea", "label": "The relative or topic I am most braced for, and my one-line plan for it:"}, {"id": "f3", "type": "textarea", "label": "The minute I will sit down with a full plate, no matter what is still in the kitchen:"}, {"id": "f4", "type": "textarea", "label": "The one thing I am choosing to let be imperfect this year:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what went as planned, what did not, and what I would hand off next time:"}]'::jsonb, array['planning', 'holidays', 'family']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('lapsed-gym-membership-decision-sheet', 'Lapsed Gym Membership Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for a client paying for a membership they do not use and feeling worse every month it renews.', 'Use it to turn a standing source of guilt into one decision: go back, change it, or cancel it on purpose.', array['Adults']::text[], '20 minutes', 'An unused membership is a small monthly reminder that the client is not who they meant to be, and the guilt usually keeps them from either going or canceling. The sheet separates the two questions: what the membership was supposed to give them, and whether this membership is the way to get it. The client lists the options (go back with a smaller plan, switch to something closer or cheaper, pause it, cancel it), writes the honest cost of each, and picks one with a date. Canceling on purpose is a legitimate outcome; the point is to end the limbo, not to make the client exercise.', '[{"id": "f0", "type": "textarea", "label": "What I hoped the membership would give me when I signed up:"}, {"id": "f1", "type": "textarea", "label": "How often I have gone in the last two months, and what usually stops me:"}, {"id": "f2", "type": "textarea", "label": "The story I tell myself each time the charge appears:"}, {"id": "f3", "type": "textarea", "label": "My options, including canceling on purpose, and the honest cost of each:"}, {"id": "f4", "type": "textarea", "label": "The one I am choosing, and the day I will act on it:"}, {"id": "f5", "type": "textarea", "label": "If I keep it: the smallest version of going that I would actually do:"}]'::jsonb, array['decisions', 'guilt', 'habits']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('organizing-the-group-gift-without-resentment-sheet', 'Organizing the Group Gift Without Resentment Sheet', 'worksheet'::resource_kind, 'A sheet for the client who ends up collecting money and buying the group gift, and resents it by the time the card is signed.', 'Use it to help a client either share the job or decline it, rather than do it all again and stew.', array['Adults']::text[], '15 minutes', 'Being the one who organizes the office or family gift looks trivial and carries a surprising load: chasing payments, choosing the thing, absorbing complaints. The sheet asks the client how they ended up with the job this time, what it costs them in hours and in feeling, and what they would rather happen. Then they draft the message that either shares the job (two names and a deadline) or passes it on. Rehearse the message in session; the hard part is sending it. Watch for the belief that nobody else will do it right, and ask what happens if they do it differently.', '[{"id": "f0", "type": "textarea", "label": "How I ended up organizing the gift this time, and how many times before:"}, {"id": "f1", "type": "textarea", "label": "What it actually costs me, in hours and in how I feel about the people involved:"}, {"id": "f2", "type": "textarea", "label": "What I tell myself about why it has to be me:"}, {"id": "f3", "type": "textarea", "label": "What I would rather happen: share it, rotate it, or hand it off entirely:"}, {"id": "f4", "type": "textarea", "label": "The message I will send, in my own words, with two names and a deadline:"}, {"id": "f5", "type": "textarea", "label": "What I will do if someone grumbles about how it was done:"}]'::jsonb, array['assertiveness', 'boundaries', 'resentment']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('barber-asked-if-i-wanted-the-usual-thought-record', 'Barber Asked If I Wanted the Usual Thought Record', 'cbt'::resource_kind, 'A thought record for an ordinary question from a barber, cashier or server that the client''s mind hears as a judgment.', 'Use it to show a client how a neutral service question becomes a verdict about them, and how to check the verdict.', array['Adults', 'Teens']::text[], '15 minutes', 'Service questions are clean examples of mind reading because they are scripted and the client supplies the meaning: the usual? becomes you are predictable and boring; anything else? becomes you have taken too long. The client records the question word for word, the automatic thought, how strongly they believed it, and the feeling. Then they list the plain reasons a person at work asks that question, and how often the worker is likely to have asked it that day. Rate the thought again at the end. Use it as a warm-up before the heavier social thought records.', '[{"id": "f0", "type": "textarea", "label": "The question, word for word, and who asked it:"}, {"id": "f1", "type": "textarea", "label": "The thought that arrived first, and how much I believed it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The feeling it produced, and how strong it was:"}, {"id": "f3", "type": "textarea", "label": "The plain reasons a person at work asks that question, and how many times they probably asked it today:"}, {"id": "f4", "type": "textarea", "label": "What I would think if I overheard the same question asked of the next customer:"}, {"id": "f5", "type": "textarea", "label": "How much I believe the first thought now (0 to 100), and what I will notice the next time I am asked:"}]'::jsonb, array['thought record', 'mind reading', 'automatic thoughts']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('send-the-email-without-a-third-reread-experiment-sheet', 'Send the Email Without a Third Reread Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment in which the client sends routine emails after one read, and records what actually comes back.', 'Use it to test the belief that one missed typo will cost the client their standing, against what really happens.', array['Adults']::text[], 'One week', 'A client who rereads every email five times is running a safety behavior, and the rereading keeps the belief alive that disaster waits in the unread draft. Agree on which emails count (routine, internal, low stakes) and set the rule: one full read, then send. For each one the client predicts what will happen, in specifics, then records the reply. Most predictions are about judgment and most replies are about logistics. Review the sheet together and look at the gap. Keep high-stakes messages out of the experiment at first; the point is to learn, not to dare.', '[{"id": "f0", "type": "textarea", "label": "The belief I am testing, in one sentence (if I send with a mistake, then…):"}, {"id": "f1", "type": "textarea", "label": "The kinds of emails that count for this experiment, and the ones that do not:"}, {"id": "f2", "type": "textarea", "label": "Before each send: what I predict will happen, specifically:"}, {"id": "f3", "type": "textarea", "label": "After each reply: what actually happened, and whether anyone mentioned an error:"}, {"id": "f4", "type": "textarea", "label": "How anxious I felt at the send button on day one, and on the last day:"}, {"id": "f5", "type": "textarea", "label": "What I learned about the gap between my predictions and the replies:"}]'::jsonb, array['behavioral experiment', 'perfectionism', 'safety behaviors']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('everyone-else-finished-the-workout-early-comparison-sheet', 'Everyone Else Finished the Workout Early Comparison Sheet', 'cbt'::resource_kind, 'A sheet for the client who leaves a class or gym convinced everyone else was faster, fitter and watching.', 'Use it to catch the comparison and the mind reading in a single ordinary moment and look at what was actually seen.', array['Adults', 'Teens']::text[], '15 minutes, after the class', 'Group exercise is a reliable trigger for comparison, because the evidence looks objective (they finished, I did not) and the conclusion does not (so I am failing). The sheet asks the client what they saw, what they concluded, and what else they could have concluded, then asks the harder question: how many of the other people did the client actually watch, and how many were watching them. Keep the sheet about thinking, not fitness; the client''s performance is not the subject.', '[{"id": "f0", "type": "textarea", "label": "The moment I noticed the comparison, and exactly what I saw:"}, {"id": "f1", "type": "textarea", "label": "What I concluded about myself from it:"}, {"id": "f2", "type": "textarea", "label": "What I concluded about what the others were thinking:"}, {"id": "f3", "type": "textarea", "label": "How many people I actually watched, and how long I spent watching them:"}, {"id": "f4", "type": "textarea", "label": "What I would think if I saw a stranger finish last in the class:"}, {"id": "f5", "type": "textarea", "label": "A fairer sentence about today''s class, written in my own words:"}]'::jsonb, array['comparison', 'mind reading', 'cognitive restructuring']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('one-cavity-means-i-let-everything-slide-sheet', 'One Cavity Means I Let Everything Slide Sheet', 'cbt'::resource_kind, 'A sheet for a small piece of bad news at a routine appointment that the client''s mind turns into a verdict on their whole life.', 'Use it to show a client how one data point becomes an overgeneralization and how to shrink it back to size.', array['Adults']::text[], '15 minutes', 'A cavity, a slightly high reading, a worn tire: small findings at routine appointments are where overgeneralization shows most clearly, because the finding is factual and the leap is not. The client writes the finding, then the sentence their mind made from it (I let everything slide, I cannot take care of myself), then looks for the words that do the leaping: everything, always, cannot. They rewrite the sentence with the finding at its actual size and a next step attached. Use the sheet when a client arrives deflated by a small thing and cannot say why.', '[{"id": "f0", "type": "textarea", "label": "The actual finding, in the words the professional used:"}, {"id": "f1", "type": "textarea", "label": "The sentence my mind made from it about me or my life:"}, {"id": "f2", "type": "textarea", "label": "The words in that sentence that do the leaping (everything, always, never, cannot):"}, {"id": "f3", "type": "textarea", "label": "Evidence from the last year that the sentence is too big:"}, {"id": "f4", "type": "textarea", "label": "The finding rewritten at its actual size, with one next step:"}, {"id": "f5", "type": "textarea", "label": "How I feel reading the small version compared with the big one:"}]'::jsonb, array['overgeneralization', 'cognitive restructuring', 'self-criticism']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('landlord-inspection-notice-catastrophe-ladder-sheet', 'Landlord Inspection Notice Catastrophe Ladder Sheet', 'cbt'::resource_kind, 'A catastrophe ladder for a notice of inspection, visit or review that the client''s mind has already turned into eviction.', 'Use it to walk a client down each rung of a feared chain of events and estimate how likely each step really is.', array['Adults']::text[], '20 minutes', 'A routine inspection notice can send a client straight to the last rung: they will find something, I will be evicted, I will have nowhere to go. The ladder writes out every rung between the notice and the feared ending, and the client estimates the likelihood of each step given the one before it. Multiply roughly and the end point is usually far smaller than it feels. Then the client writes what they would actually do at each rung if it happened. Use it for any official letter, performance review or audit the client has catastrophized.', '[{"id": "f0", "type": "textarea", "label": "The notice I received, and what it actually says:"}, {"id": "f1", "type": "textarea", "label": "The worst ending my mind has reached, in one sentence:"}, {"id": "f2", "type": "textarea", "label": "Every rung between the notice and that ending, in order:"}, {"id": "f3", "type": "textarea", "label": "For each rung: how likely it is, given the one before (a rough percentage or a word):"}, {"id": "f4", "type": "textarea", "label": "At each rung, what I would actually do if it happened:"}, {"id": "f5", "type": "textarea", "label": "What preparing for the real inspection looks like, in two or three steps:"}]'::jsonb, array['catastrophizing', 'decatastrophizing', 'problem solving']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('mind-as-a-backseat-driver-on-every-trip-page', 'Mind as a Backseat Driver on Every Trip Page', 'act'::resource_kind, 'A defusion page that casts the running commentary of the mind as a backseat driver who comments but does not steer.', 'Use it to help a client hear the mind''s directions as commentary and keep their own hands on the wheel.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients recognize the backseat driver immediately: the voice that says slow down, you missed the turn, you should have taken the highway, from a seat with no pedals. The page asks the client to write a day''s commentary in that voice, then to notice who was actually driving the whole time. The move is not to silence the passenger (they never get out) but to drive the route the client chose while the commentary runs. End with one real choice the client will make this week with the voice talking and their hands still on the wheel.', '[{"id": "f0", "type": "textarea", "label": "A typical day''s commentary from my backseat driver, written as it sounds:"}, {"id": "f1", "type": "textarea", "label": "The directions it gave today that I followed without checking where they led:"}, {"id": "f2", "type": "textarea", "label": "Who was actually steering during all of that commentary:"}, {"id": "f3", "type": "textarea", "label": "A route I want to take this week that the backseat driver will object to:"}, {"id": "f4", "type": "textarea", "label": "What I will say to the voice (if anything) while I keep driving:"}, {"id": "f5", "type": "textarea", "label": "After the trip: what the voice said, and where I actually went:"}]'::jsonb, array['defusion', 'metaphor', 'ACT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('values-at-the-bottom-of-the-laundry-basket-page', 'Values at the Bottom of the Laundry Basket Page', 'act'::resource_kind, 'A values page that finds what matters inside the most tedious chore the client faces every week.', 'Use it to connect a dull repeated task to a value, so the client does it for a reason rather than against resentment.', array['Adults']::text[], '15 minutes', 'Chores are where values disappear from view, and a client who resents every load of laundry is usually missing the reason it matters to them, not the energy. The page takes one tedious task and asks what it quietly serves: a home that feels calm, a child with a clean uniform, a body that is cared for. Then the client writes the task again as an act of that value and notices whether it feels different. This is not about enjoying laundry. It is about doing the task from a chosen direction instead of under protest.', '[{"id": "f0", "type": "textarea", "label": "The chore I resent most, and what my mind says while I do it:"}, {"id": "f1", "type": "textarea", "label": "Who or what the chore quietly serves when it gets done:"}, {"id": "f2", "type": "textarea", "label": "The value underneath that (care, order, reliability, something else):"}, {"id": "f3", "type": "textarea", "label": "The chore rewritten as an act of that value, in one sentence:"}, {"id": "f4", "type": "textarea", "label": "The next time I do it: what I will notice while doing it from that direction:"}, {"id": "f5", "type": "textarea", "label": "Whether it felt any different, and what I want to carry into the next dull task:"}]'::jsonb, array['values', 'committed action', 'ACT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('snow-globe-settling-present-moment-page', 'Snow Globe Settling Present Moment Page', 'act'::resource_kind, 'A present-moment page that uses a shaken snow globe as the image for a stirred-up mind coming to rest on its own.', 'Use it to give a client a picture of letting thoughts settle rather than trying to grab each flake out of the air.', array['Adults', 'Teens']::text[], '10 minutes', 'After a stressful hour the mind looks like a shaken snow globe, and most clients try to fix it by snatching at individual flakes. The page walks through the image: the shake, the storm, the slow settling that happens only when the globe is set down and left alone. The client practices setting the globe down for two minutes, attention on the breath or the feet, and watches what settles and what keeps swirling. Not everything settles, and the page says so. Use it as a short practice at the start of a session when the client arrives stirred up.', '[{"id": "f0", "type": "textarea", "label": "What shook my snow globe today, and what the storm inside looks like:"}, {"id": "f1", "type": "textarea", "label": "The flakes I keep trying to catch and sort while they are still in the air:"}, {"id": "f2", "type": "textarea", "label": "What I noticed in two minutes of setting the globe down and just watching:"}, {"id": "f3", "type": "textarea", "label": "What settled, and what kept swirling:"}, {"id": "f4", "type": "textarea", "label": "Where I could set the globe down for two minutes during a normal day:"}, {"id": "f5", "type": "textarea", "label": "What I want to remember the next time I am shaken:"}]'::jsonb, array['present moment', 'mindfulness', 'metaphor']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('thoughts-as-spam-folder-mail-page', 'Thoughts as Spam Folder Mail Page', 'act'::resource_kind, 'A defusion page that treats repetitive unhelpful thoughts as mail in a spam folder: arriving, flagged, left unopened.', 'Use it to help a client notice a familiar thought, label it, and leave it unopened instead of replying to it.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients know spam when they see it in an inbox and still open every message their mind sends. The page asks them to list the thoughts that arrive on a loop (you will mess this up, nobody really likes you) and to write each as a spam subject line: the sender, the familiar hook, the urgency. Then they practice the move: notice it has arrived, label it as the usual sender, leave it unopened and go back to what they were doing. Replying, arguing and deleting all count as opening. The last line asks what they got on with while the message sat there.', '[{"id": "f0", "type": "textarea", "label": "The thoughts that arrive on a loop, written as subject lines in my spam folder:"}, {"id": "f1", "type": "textarea", "label": "The sender behind most of them, and the hook that usually gets me to open:"}, {"id": "f2", "type": "textarea", "label": "What happens when I open one and start replying:"}, {"id": "f3", "type": "textarea", "label": "The label I will give the next one when it lands (the usual, the worry sender, something else):"}, {"id": "f4", "type": "textarea", "label": "What I was doing when it arrived, and what I went back to:"}, {"id": "f5", "type": "textarea", "label": "What I notice about the message after a day of leaving it unopened:"}]'::jsonb, array['defusion', 'automatic thoughts', 'ACT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('willing-to-be-a-beginner-at-the-ice-rink-page', 'Willing to Be a Beginner at the Ice Rink Page', 'act'::resource_kind, 'A willingness page for trying something the client is bad at in public, with the wobble and the embarrassment on board.', 'Use it to help a client choose a beginner moment on purpose and make room for the discomfort that comes with it.', array['Adults', 'Teens']::text[], '20 minutes, then the activity', 'Being a visible beginner is a willingness exercise most clients avoid without noticing, and a skating rink, a pottery class or a language meetup is a clean place to practice. The client picks one beginner activity, writes what their mind predicts (everyone will watch, I will fall, I am too old), and names the value that makes the wobble worth it. Then they go, and the page asks what showed up and whether they stayed. Falling is allowed. The exercise is the staying, not the skating.', '[{"id": "f0", "type": "textarea", "label": "The beginner thing I have been avoiding, and the value that makes it worth trying:"}, {"id": "f1", "type": "textarea", "label": "What my mind predicts will happen, in its own words:"}, {"id": "f2", "type": "textarea", "label": "The feelings I am willing to have in order to go (embarrassment, clumsiness, fear of falling):"}, {"id": "f3", "type": "textarea", "label": "The time and place I will go, and who I will tell:"}, {"id": "f4", "type": "textarea", "label": "During it: what showed up, and whether I stayed:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what the beginner hour gave me that avoiding it could not:"}]'::jsonb, array['willingness', 'courage', 'values']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('fast-skill-when-a-coworker-asks-to-swap-shifts-card', 'FAST Skill When a Coworker Asks to Swap Shifts Card', 'dbt'::resource_kind, 'A FAST card for declining or negotiating a shift swap without over-apologizing or giving up a plan that matters.', 'Use it to help a client keep their self-respect in a small request they would usually cave to.', array['Adults']::text[], '10 minutes', 'The shift swap is a small ask that lands hard on a client who cannot say no: they trade away a day off and spend the week resenting it. FAST (be Fair, no Apologies, Stick to values, be Truthful) fits the moment exactly. The card walks through what is fair to both people, the apology the client would normally add and why to leave it out, the value the day off serves, and the truthful reason instead of an invented excuse. Rehearse the two sentences out loud. Watch for the client who agrees to the swap and then asks for help resenting it.', '[{"id": "f0", "type": "textarea", "label": "The request, and what I would usually say in the first three seconds:"}, {"id": "f1", "type": "textarea", "label": "Fair: what is reasonable for both of us here, including for me:"}, {"id": "f2", "type": "textarea", "label": "Apologies: the sorry I would normally add, and what the sentence sounds like without it:"}, {"id": "f3", "type": "textarea", "label": "Stick to values: what the day off or the plan actually serves:"}, {"id": "f4", "type": "textarea", "label": "Truthful: the real reason, in one sentence, with no invented excuse:"}, {"id": "f5", "type": "textarea", "label": "My two-sentence answer, rehearsed out loud:"}]'::jsonb, array['FAST', 'assertiveness', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-current-thoughts-on-the-commute-card', 'Mindfulness of Current Thoughts on the Commute Card', 'dbt'::resource_kind, 'A card for practicing mindfulness of current thoughts during a daily commute, watching thoughts come and go like traffic.', 'Use it to give a client a daily, built-in slot for watching thoughts as thoughts instead of arriving at work already argued out.', array['Adults']::text[], 'The length of the commute, daily for a week', 'The commute is where many clients rehearse the day''s arguments, and it is also a reliable twenty minutes for practice. Mindfulness of current thoughts asks the client to observe each thought as a thought (there is the worry about the meeting), let it pass like a car in the other lane, and return to the road or the window. Not pushing thoughts away, not following them. The card logs one commute a day: what showed up, how often the client got pulled along, how they came back. Drivers keep eyes on the road; the practice is light attention, not closed eyes.', '[{"id": "f0", "type": "textarea", "label": "My commute: how long, how I travel, and what my mind usually does during it:"}, {"id": "f1", "type": "textarea", "label": "Today''s thoughts, named as thoughts (there is a thought about…), not argued with:"}, {"id": "f2", "type": "textarea", "label": "How many times I got pulled into one, and what pulled me back:"}, {"id": "f3", "type": "textarea", "label": "What I noticed about the thoughts by the end of the trip:"}, {"id": "f4", "type": "textarea", "label": "How I arrived compared with a normal day:"}, {"id": "f5", "type": "textarea", "label": "One thought I am willing to let drive past tomorrow without following it:"}]'::jsonb, array['mindfulness', 'DBT', 'thoughts']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('observe-the-itch-without-scratching-card', 'Observe the Itch Without Scratching Card', 'dbt'::resource_kind, 'An observe-skill card using an ordinary itch to practice feeling an urge rise, peak and fade without acting on it.', 'Use it to teach the shape of an urge with a harmless one, before the client applies it to the urges that cost them.', array['Adults', 'Teens']::text[], 'Five minutes, several times', 'An itch is a perfect classroom for urges: it is real, it demands action, and it passes if left alone. The card asks the client to sit with the next itch for two minutes, observing where it is, how it changes, when it peaks and what the mind says (just scratch it, this is pointless). Then they record what happened. The lesson transfers to urges that matter: to check, to text, to use. Keep the debrief on the shape of the urge, not on willpower. Two minutes is enough; the goal is noticing, not endurance.', '[{"id": "f0", "type": "textarea", "label": "Where the itch was, and how strong it felt at the start (0 to 10):"}, {"id": "f1", "type": "textarea", "label": "What my mind said while I did not scratch:"}, {"id": "f2", "type": "textarea", "label": "How the itch changed over two minutes: rose, peaked, moved, faded:"}, {"id": "f3", "type": "textarea", "label": "What it felt like at the end, and whether I scratched:"}, {"id": "f4", "type": "textarea", "label": "An urge in my life that follows the same shape:"}, {"id": "f5", "type": "textarea", "label": "What I want to remember from the itch the next time that urge arrives:"}]'::jsonb, array['observe', 'urges', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('cope-ahead-for-the-office-holiday-party-card', 'Cope Ahead for the Office Holiday Party Card', 'dbt'::resource_kind, 'A cope-ahead card for an office party, rehearsing the hard moments, the exit, and the skill the client will use at each.', 'Use it to help a client walk into a work social event with a plan already rehearsed instead of improvising under pressure.', array['Adults']::text[], '20 minutes, the week before', 'The office party combines small talk, alcohol, bosses and performance in one room, and clients who dread it usually either skip it or white-knuckle it. Cope ahead rehearses the specific hard moments in imagination: arriving alone, the drink offer, the question about personal life, the moment of wanting to leave. For each the client names the skill (GIVE, a prepared line, a paced breath, the exit) and imagines using it well. Then they rehearse the whole evening once, slowly. Include a planned arrival and departure time; a known end makes the middle easier.', '[{"id": "f0", "type": "textarea", "label": "The event, when I will arrive, and when I plan to leave:"}, {"id": "f1", "type": "textarea", "label": "The three moments I am most braced for:"}, {"id": "f2", "type": "textarea", "label": "For each moment: the skill or line I will use, in my own words:"}, {"id": "f3", "type": "textarea", "label": "The whole evening rehearsed in my mind, from the door to the exit, in a few sentences:"}, {"id": "f4", "type": "textarea", "label": "The thoughts that showed up during the rehearsal, and how I handled them:"}, {"id": "f5", "type": "textarea", "label": "After the party: which moments came, which did not, and what worked:"}]'::jsonb, array['cope ahead', 'social skills', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-quitting-without-notice-grid', 'Pros and Cons of Quitting Without Notice Grid', 'dbt'::resource_kind, 'A pros and cons grid for the urge to walk out of a job today, weighing acting on the urge against staying one more week.', 'Use it to slow a hot decision long enough for the client to see both columns before they act.', array['Adults']::text[], '20 minutes', 'The urge to quit on the spot is a crisis urge dressed as a decision, and the DBT grid fits it: pros and cons of acting on the urge, pros and cons of not acting, each in both the short term and the long. Fill it in session while the urge is warm. The client is often surprised by the short-term pros of staying (a reference, a paycheck, leaving on their own terms) and the long-term cons of walking. The grid does not decide whether to leave the job; it decides whether to leave it today. If the job is genuinely harming them, the sheet also lists the planned way out.', '[{"id": "f0", "type": "textarea", "label": "The situation, and what the urge is telling me to do right now:"}, {"id": "f1", "type": "textarea", "label": "Pros of walking out today: this week, and six months from now:"}, {"id": "f2", "type": "textarea", "label": "Cons of walking out today: this week, and six months from now:"}, {"id": "f3", "type": "textarea", "label": "Pros of staying one more week while I plan: this week, and six months from now:"}, {"id": "f4", "type": "textarea", "label": "Cons of staying one more week: this week, and six months from now:"}, {"id": "f5", "type": "textarea", "label": "What the grid says to do today, and the first planned step if I am leaving:"}]'::jsonb, array['pros and cons', 'work', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('thanksgiving-table-seating-and-topics-plan-for-partners', 'Thanksgiving Table Seating and Topics Plan for Partners', 'couples'::resource_kind, 'A plan for partners hosting or attending a holiday meal: who sits where, which topics are off the table, and the signal for help.', 'Use it to get both partners on the same side before the meal instead of discovering their differences in front of the family.', array['Couples']::text[], '30 minutes, the week before', 'Holiday meals strain couples because each partner is managing their own family and assuming the other will notice. The sheet has both partners name the relative they most need help with and what help looks like, agree on the topics that are off limits and who redirects when one surfaces, and pick a discreet signal for I need you to step in. Seating is planned on purpose. Finish with when they will leave and who says so. Each partner fills in their own lines before comparing; the comparing is the work.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the relative or dynamic I most need help with, and what helping me looks like:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the relative or dynamic I most need help with, and what helping me looks like:"}, {"id": "f2", "type": "textarea", "label": "The topics we agree are off the table, and who will change the subject when one comes up:"}, {"id": "f3", "type": "textarea", "label": "Where we each want to sit, and who sits next to whom on purpose:"}, {"id": "f4", "type": "textarea", "label": "Our signal for I need you now, and what the other does when they see it:"}, {"id": "f5", "type": "textarea", "label": "When we will leave, who says it is time, and how we will debrief in the car:"}]'::jsonb, array['holidays', 'family', 'teamwork']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('car-clutter-and-empty-gas-tank-pact-for-partners', 'Car Clutter and Empty Gas Tank Pact for Partners', 'couples'::resource_kind, 'A pact for the shared car: who refuels, who clears the clutter, and how to raise it without the drive becoming a fight.', 'Use it to settle a recurring small resentment with a clear agreement rather than another argument at the pump.', array['Couples']::text[], '20 minutes', 'The shared car is a daily site of small resentment: one partner returns it on empty, the other leaves it full of cups and receipts, and both feel disrespected. The sheet asks each partner what bothers them about the car and what they think the other does not notice, then sets a few plain agreements (the tank never goes below a quarter, the clutter gets cleared on Sundays, whoever drives last plugs it in). The last part matters most: the words each partner will use to raise a slip, and how the other will answer without defending.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what bothers me about the shared car, and what I think my partner does not notice:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what bothers me about the shared car, and what I think my partner does not notice:"}, {"id": "f2", "type": "textarea", "label": "Our agreements, in plain words (fuel level, clutter, charging, keys):"}, {"id": "f3", "type": "textarea", "label": "How Partner A will mention a slip, and how Partner B will answer:"}, {"id": "f4", "type": "textarea", "label": "How Partner B will mention a slip, and how Partner A will answer:"}, {"id": "f5", "type": "textarea", "label": "The date we will check whether the pact is holding:"}]'::jsonb, array['household', 'fairness', 'repair']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('who-replies-to-the-group-invite-rule-for-partners', 'Who Replies to the Group Invite Rule for Partners', 'couples'::resource_kind, 'A rule for couples who get the same invitation and each wait for the other to answer, or answer differently.', 'Use it to end the standoff over invitations with a shared way of deciding and replying.', array['Couples']::text[], '15 minutes', 'A couple invited together often answers apart: one says yes in the group chat before checking, or both stay silent until the host chases them. The sheet has each partner describe what they do with an invitation and what they wish the other did, then builds a rule: who checks with whom, how long the check takes, who replies and in what words. It also covers the harder case, where one wants to go and one does not. Keep the rule simple enough to follow on a phone in a parking lot.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I usually do when an invitation arrives, and what I wish you did:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I usually do when an invitation arrives, and what I wish you did:"}, {"id": "f2", "type": "textarea", "label": "Our rule: who checks with whom, how fast, and who sends the reply:"}, {"id": "f3", "type": "textarea", "label": "When one of us wants to go and the other does not: how we decide, and how we tell the host:"}, {"id": "f4", "type": "textarea", "label": "The words we will use to decline together without blaming each other:"}, {"id": "f5", "type": "textarea", "label": "The next invitation we expect, and how we will handle it:"}]'::jsonb, array['communication', 'social', 'decisions']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('argument-that-started-in-the-parking-lot-repair-sheet', 'Argument That Started in the Parking Lot Repair Sheet', 'couples'::resource_kind, 'A repair sheet for the fight that began in the parking lot and rode home in silence, for both partners to finish properly.', 'Use it to help partners close an argument that was never resolved, only abandoned at the front door.', array['Couples']::text[], '30 minutes', 'Many fights are not ended, just interrupted by arrival: the car door closes and both partners go to separate rooms. The sheet is filled in by each partner first, then together: what the fight was about on the surface and what it was about underneath, the moment each wishes they had said something different, and the one thing they each need to hear now. Then they agree on what to do differently the next time a fight starts somewhere it cannot finish. Keep the repair about the pattern, not about who was right.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what the argument was about on the surface, and what I think it was really about:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what the argument was about on the surface, and what I think it was really about:"}, {"id": "f2", "type": "textarea", "label": "Partner A: the moment I wish I had handled differently, and the one thing I need to hear from you:"}, {"id": "f3", "type": "textarea", "label": "Partner B: the moment I wish I had handled differently, and the one thing I need to hear from you:"}, {"id": "f4", "type": "textarea", "label": "What we each heard in the other''s lines that we did not know before:"}, {"id": "f5", "type": "textarea", "label": "Next time a fight starts somewhere it cannot finish: our pause phrase and when we will come back to it:"}]'::jsonb, array['repair', 'conflict', 'communication']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('sunday-evening-dread-shared-wind-down-plan-for-partners', 'Sunday Evening Dread Shared Wind-Down Plan for Partners', 'couples'::resource_kind, 'A shared plan for the Sunday evening slump, for couples where one or both partners get quiet and tense before the work week.', 'Use it to give partners a way to be together through the Sunday dread instead of drifting apart into their phones.', array['Couples']::text[], '20 minutes', 'Sunday evening dread is common and rarely discussed between partners; one gets tense and withdrawn, the other feels shut out, and the evening is lost. The sheet asks each partner what Sunday evening is like for them and what they need from the other (company, space, a plan, no questions about the week). Then they design an evening together: a fixed small ritual, a cutoff for work talk and screens, and the words for I am in the dread. Nothing on it fixes Monday. It gives Sunday a shape the two can share.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what Sunday evening is like for me, and what I need from you during it:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what Sunday evening is like for me, and what I need from you during it:"}, {"id": "f2", "type": "textarea", "label": "Our small Sunday ritual, and the time it starts:"}, {"id": "f3", "type": "textarea", "label": "When work talk and screens stop, and what we do instead:"}, {"id": "f4", "type": "textarea", "label": "The words either of us can say to mean I am in the dread tonight, and what the other does:"}, {"id": "f5", "type": "textarea", "label": "After the first Sunday: what helped, and what we will change:"}]'::jsonb, array['stress', 'connection', 'routine']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('paper-chain-countdown-waiting-craft', 'Paper Chain Countdown Waiting Craft', 'kids'::resource_kind, 'A paper chain the child makes with a parent to count down to a hard-to-wait-for day, tearing off one link each evening.', 'Use it to give a child a visible, shrinking picture of a wait, and a parent a daily minute to talk about it.', array['Children']::text[], '20 minutes to make, one minute daily', 'Waiting for a trip, a visit or a move is hard for a child with no sense of how long a week is, and the questions wear parents down. The child and parent cut a strip for each day, write or draw one small thing to look forward to on each, and loop them into a chain. Each evening the child tears off a link and the parent reads what is on it and asks one question about the day. For a dreaded event (a procedure, a parent leaving), the links hold comfort plans rather than treats. The parent''s job is the nightly minute, not the craft.', '[{"id": "f0", "type": "textarea", "label": "What I am waiting for, and how many sleeps until it comes:"}, {"id": "f1", "type": "textarea", "label": "The small things I drew or wrote on my links to look forward to:"}, {"id": "f2", "type": "textarea", "label": "What my grown-up and I say when we tear off a link each night:"}, {"id": "f3", "type": "textarea", "label": "What I will do with the chain when it is all gone:"}, {"id": "f4", "type": "textarea", "label": "For my grown-up: how I will use the nightly link to ask about feelings, not just the countdown:"}]'::jsonb, array['kids', 'waiting', 'drawing']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('cardboard-box-robot-feelings-buttons-craft', 'Cardboard Box Robot Feelings Buttons Craft', 'kids'::resource_kind, 'A cardboard robot with labeled feeling buttons the child presses to show how they feel, made with a parent.', 'Use it to give a child who cannot find the words a robot that says the feeling for them.', array['Children']::text[], '45 minutes to build, then daily', 'A child who shuts down when asked how they feel will often press a button. The child and parent turn a box into a robot and glue on bottle-cap buttons, each labeled with a feeling the child picks and a color they choose. The child presses the button for how they feel and, if they want, says what the robot would do about it. The parent''s job is to ask the robot, not the child, and to respond to the button without quizzing. Add buttons over the weeks; the first set is usually four or five.', '[{"id": "f0", "type": "textarea", "label": "The feelings on my robot''s buttons, and the color I gave each one:"}, {"id": "f1", "type": "textarea", "label": "What my robot does when I press the mad button, and the worried one:"}, {"id": "f2", "type": "textarea", "label": "The button I pressed today, and why:"}, {"id": "f3", "type": "textarea", "label": "A button I want to add next week:"}, {"id": "f4", "type": "textarea", "label": "For my grown-up: how I will ask the robot each day, and what I will do when my child presses a hard button:"}]'::jsonb, array['kids', 'emotion identification', 'drawing']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('frozen-toy-ice-rescue-patience-play', 'Frozen Toy Ice Rescue Patience Play', 'kids'::resource_kind, 'A play activity where a small toy is frozen in ice and the child rescues it slowly with warm water, salt and patience.', 'Use it to give a child a hands-on experience of waiting and working steadily at something that will not hurry.', array['Children']::text[], '15 minutes to set up the night before, 30 minutes to play', 'Frozen toy rescue is a patience game that feels like an adventure. The parent freezes a small toy in a cup of water overnight; the next day the child frees it using a spoon, warm water, a pinch of salt and time. The point is the pace: hitting the ice does little, warm water and waiting do a lot. The parent narrates calmly (it is working, it is just slow), names the frustration when it shows up, and does not take over. Afterward they talk about one other thing in the child''s life that works like the ice.', '[{"id": "f0", "type": "textarea", "label": "How long it took to rescue my toy, and what worked best:"}, {"id": "f1", "type": "textarea", "label": "The moment I most wanted to smash the ice, and what I did instead:"}, {"id": "f2", "type": "textarea", "label": "What my grown-up said that helped me keep going:"}, {"id": "f3", "type": "textarea", "label": "One thing in my life that is slow like the ice and cannot be hurried:"}, {"id": "f4", "type": "textarea", "label": "For my grown-up: what I noticed about my child''s patience, and how I stayed out of the rescue:"}]'::jsonb, array['kids', 'patience', 'frustration']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('shaving-cream-tray-slow-letters-play', 'Shaving Cream Tray Slow Letters Play', 'kids'::resource_kind, 'A sensory play where the child writes words or feelings slowly in a tray of shaving cream with one finger, with a parent alongside.', 'Use it to settle a wound-up child through slow sensory work and give them a soft place to write a hard word.', array['Children']::text[], '15 minutes', 'Shaving cream on a tray is messy, cold, and calming, and slow finger writing in it works for a child who is too stirred up to sit and talk. The parent spreads a thin layer, and the two take turns writing one word or drawing one shape slowly, then smoothing it away. Feelings can be written and wiped with no one keeping them. The parent writes too, sets the slow pace, and says nothing about spelling. Use it before bedtime or after a hard afternoon, and let the child decide when the tray is done.', '[{"id": "f0", "type": "textarea", "label": "The words or pictures I made in the cream today:"}, {"id": "f1", "type": "textarea", "label": "A feeling I wrote and then smoothed away:"}, {"id": "f2", "type": "textarea", "label": "What the cream felt like on my finger when I went slowly:"}, {"id": "f3", "type": "textarea", "label": "How my body felt after we cleaned up compared with before:"}, {"id": "f4", "type": "textarea", "label": "For my grown-up: when I will offer the tray, and how I will keep the pace slow and the spelling out of it:"}]'::jsonb, array['kids', 'self-soothing', 'body awareness']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('pinecone-bird-feeder-watching-quiet-play', 'Pinecone Bird Feeder Watching Quiet Play', 'kids'::resource_kind, 'A pinecone bird feeder the child makes and hangs with a parent, then watches from a window for a quiet few minutes a day.', 'Use it to build a small daily stillness practice for a child, with a reason to sit quietly and something real to look at.', array['Children']::text[], '30 minutes to make, five minutes daily', 'A child who cannot sit still will sit still for a bird. The child and parent coat a pinecone in nut-free spread or suet, roll it in seed, hang it outside a window, and then begin the real activity: a few minutes a day of quiet watching, noticing what comes, what color it is, what it does. The parent sits too, phone away, and keeps a shared tally. Birds take days to find a feeder, so the waiting is part of the practice. Afterward, ask what the child''s body did while watching.', '[{"id": "f0", "type": "textarea", "label": "How we made our feeder, and where we hung it:"}, {"id": "f1", "type": "textarea", "label": "The birds or animals we have seen so far, and what they did:"}, {"id": "f2", "type": "textarea", "label": "What my body did while I watched quietly (still, wiggly, calm, bored):"}, {"id": "f3", "type": "textarea", "label": "How many days it took before the first bird came, and what waiting was like:"}, {"id": "f4", "type": "textarea", "label": "For my grown-up: the time of day we will watch, and how I will sit with my child without directing:"}]'::jsonb, array['kids', 'present moment', 'patience']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('hum-the-feeling-guess-the-mood-game', 'Hum the Feeling Guess the Mood Game', 'game'::resource_kind, 'A group game where players hum a feeling without words and the others guess it, with a debrief on how feelings sound.', 'Use it to get a group noticing tone, pace and volume as carriers of emotion, with laughter to loosen the room.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Rules: write feelings on slips (excited, nervous, bored, furious, calm, sad). On each turn a player draws a slip and hums it, no words, no faces if you want it harder, for ten seconds. The others guess; a correct guess earns a point for the hummer and the guesser. Play two rounds so everyone hums twice. Debrief: which feelings were easy to hear and which were confused with each other, how pace and volume gave them away, and when the players have heard a feeling in a family member''s voice before any words. Fits a mixed-age group.', '[{"id": "f0", "type": "textarea", "label": "The feeling I hummed, and whether the group guessed it:"}, {"id": "f1", "type": "textarea", "label": "The two feelings the group kept mixing up, and why I think that happened:"}, {"id": "f2", "type": "textarea", "label": "What gave a feeling away: speed, loudness, high or low, something else:"}, {"id": "f3", "type": "textarea", "label": "A time I heard a feeling in someone''s voice before they said anything:"}, {"id": "f4", "type": "textarea", "label": "What I want to listen for this week in my own voice:"}]'::jsonb, array['group game', 'emotion identification', 'listening']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('kind-rumor-mill-pass-it-forward-game', 'Kind Rumor Mill Pass It Forward Game', 'game'::resource_kind, 'A game that turns the rumor mill around: players pass a true kind observation about someone down the line and see how it arrives.', 'Use it to show a group how messages change as they travel and to practice saying something kind about a peer out loud.', array['Teens', 'Groups']::text[], '25 minutes', 'Rules: players sit in a line. The leader whispers a specific kind observation about one player (she stayed to help clean up on Tuesday) to the first in line, who whispers it on, and so on; the last player says it aloud. Compare the start and the end. Then rotate so a different player starts, with a new kind observation of their own choosing about anyone in the room, and repeat until everyone has been the subject once. Debrief: what got lost or added, how it felt to be the subject, and how the same mechanism works with unkind rumors. Keep observations specific and true.', '[{"id": "f0", "type": "textarea", "label": "The kind message I started, and how it sounded when it reached the end:"}, {"id": "f1", "type": "textarea", "label": "What the message about me was, and how it felt to hear it said out loud:"}, {"id": "f2", "type": "textarea", "label": "What got lost or added as the messages traveled:"}, {"id": "f3", "type": "textarea", "label": "How this is like what happens with an unkind rumor at school or work:"}, {"id": "f4", "type": "textarea", "label": "One specific kind thing I will say directly to someone this week instead of passing it on:"}]'::jsonb, array['group game', 'kindness', 'social skills']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('mystery-bag-texture-guess-grounding-game', 'Mystery Bag Texture Guess Grounding Game', 'game'::resource_kind, 'A grounding game where players reach into a bag, describe an object by touch alone, and the group guesses what it is.', 'Use it to practice describing sensations in plain words and to give a group a grounding skill that feels like play.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Rules: fill a cloth bag with everyday objects (a pinecone, a spoon, a sponge, a key, a sock). On each turn a player reaches in without looking and describes one object using only texture, temperature, shape and size words for thirty seconds, no naming. The group guesses; the player gets a point for every describing word they used before the guess landed. Every player takes two turns. Debrief: how the describing changed their attention, what it was like to stay with the object, and when they could reach for five texture words in their own day to come back to the present.', '[{"id": "f0", "type": "textarea", "label": "The object I described, and the words I used before anyone guessed:"}, {"id": "f1", "type": "textarea", "label": "The hardest part: not naming it, or finding the words:"}, {"id": "f2", "type": "textarea", "label": "What happened to my attention while I was describing:"}, {"id": "f3", "type": "textarea", "label": "Five things within reach right now that I could describe the same way:"}, {"id": "f4", "type": "textarea", "label": "A moment this week when I could use texture words to come back to the room:"}]'::jsonb, array['group game', 'grounding', 'body awareness']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('yes-and-improv-agreement-game', 'Yes And Improv Agreement Game', 'game'::resource_kind, 'An improv game where every line must begin with yes, and, building on the last player''s idea instead of blocking it.', 'Use it to let a group feel the difference between adding to someone''s idea and shutting it down.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Rules: two players start a scene from a prompt (planning a picnic, fixing a leak). Every line must begin with yes, and, accepting what was just said and adding one thing. A no, a but, or an ignored idea ends the scene and the next pair steps in. Run short scenes so everyone plays twice. Debrief: what it felt like to be agreed with, where the urge to block showed up, and how a yes-and changes a real conversation at home or work. The second round can add a twist: the scene is a disagreement, still played with yes, and.', '[{"id": "f0", "type": "textarea", "label": "The prompt my scene started from, and where the yes-and took it:"}, {"id": "f1", "type": "textarea", "label": "The moment I most wanted to say but or no, and what I said instead:"}, {"id": "f2", "type": "textarea", "label": "What it felt like to have my idea accepted and built on:"}, {"id": "f3", "type": "textarea", "label": "A conversation this week where I blocked instead of building:"}, {"id": "f4", "type": "textarea", "label": "How I could yes-and that conversation next time without agreeing to everything:"}]'::jsonb, array['group game', 'communication', 'listening']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('statue-garden-freeze-and-breathe-game', 'Statue Garden Freeze and Breathe Game', 'game'::resource_kind, 'A movement game where players wander as visitors and freeze as statues on a signal, holding still for one slow breath.', 'Use it to give a group a playful way to practice stopping, holding still and breathing before moving again.', array['Children', 'Groups']::text[], '15 minutes', 'Rules: players move around the room as visitors to a garden. When the leader says statues, everyone freezes in a pose and takes one slow breath in and out before the leader says visitors again. A player who moves before the breath is done becomes the next leader. Add rounds where the freeze must show a feeling (a proud statue, a nervous statue) and the others name it. Play for about ten minutes. Debrief: what happened in the body during the freeze, whether the breath got easier, and where in the day a one-breath freeze would help.', '[{"id": "f0", "type": "textarea", "label": "My favorite statue pose, and the feeling it showed:"}, {"id": "f1", "type": "textarea", "label": "What my body did while I held still for the breath:"}, {"id": "f2", "type": "textarea", "label": "Whether freezing got easier or harder as the game went on:"}, {"id": "f3", "type": "textarea", "label": "A time in my day when I could freeze for one breath before I act:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the other statues when I was the leader:"}]'::jsonb, array['group game', 'breathing', 'kids']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('safe-enough-minutes-map-for-a-typical-day-sheet', 'Safe Enough Minutes Map for a Typical Day Sheet', 'worksheet'::resource_kind, 'A map of an ordinary day marking the minutes the client already feels safe enough, to build from rather than start from zero.', 'Use it to show a client that safety is not absent from their day, and to find where the next safe minute could be added.', array['Adults', 'Teens']::text[], '25 minutes', 'A client living on alert often believes they are never calm, and the belief itself keeps the alarm on. The sheet walks through a typical day hour by hour and marks the minutes the client would call safe enough: the shower with the door locked, the car with the radio on, the dog on the couch. Then it asks what those minutes have in common and where one more could be placed. Stay on the stabilizing side; this is about the present day, not the past, and nothing on it asks what happened. Complete it in session the first time.', '[{"id": "f0", "type": "textarea", "label": "My day, hour by hour, with a mark beside every stretch that already feels safe enough:"}, {"id": "f1", "type": "textarea", "label": "What those safe enough minutes have in common (place, people, sound, light, a lock, an animal):"}, {"id": "f2", "type": "textarea", "label": "The hours with no mark at all, and what is different about them:"}, {"id": "f3", "type": "textarea", "label": "One more safe enough minute I could add this week, and where it would go:"}, {"id": "f4", "type": "textarea", "label": "What I will do with that minute when it arrives, instead of checking whether I deserve it:"}, {"id": "f5", "type": "textarea", "label": "After a week: whether the minute held, and what I learned about my own safety signals:"}]'::jsonb, array['PTSD and trauma', 'stabilizing', 'safety']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('if-i-relax-something-bad-will-happen-thought-check-sheet', 'If I Relax Something Bad Will Happen Thought Check Sheet', 'cbt'::resource_kind, 'A thought check for the belief that letting the guard down is what causes harm, tested gently against the client''s experience.', 'Use it to loosen the idea that vigilance is what has kept the client safe, so that resting stops feeling like a risk.', array['Adults']::text[], '20 minutes, in session', 'Many clients who have been hurt treat alertness as the thing that protected them and relaxation as the thing that invites harm. The sheet writes the belief out plainly, then looks at it: times the client was alert and something bad still happened, times they relaxed and nothing did, and what vigilance actually costs them now. The aim is not to argue the client into relaxing but to let them see the belief as a belief. Go slowly and stay with the present; do not invite the story of what happened. Pause if the client''s arousal climbs.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my own words (if I let my guard down, then…):"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it right now (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "Times I was fully alert and something hard happened anyway:"}, {"id": "f3", "type": "textarea", "label": "Times I relaxed, even briefly, and nothing bad followed:"}, {"id": "f4", "type": "textarea", "label": "What staying on guard costs me now, in sleep, body and relationships:"}, {"id": "f5", "type": "textarea", "label": "A smaller, truer version of the belief I could try carrying this week:"}]'::jsonb, array['PTSD and trauma', 'core beliefs', 'hypervigilance']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('nervous-system-as-a-loyal-guard-dog-page', 'Nervous System as a Loyal Guard Dog Page', 'act'::resource_kind, 'An acceptance page that pictures the overactive alarm as a loyal guard dog who barks at everything because it once had reason to.', 'Use it to help a client meet their startle and alertness with some kindness rather than fighting or being ashamed of it.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients fight their startle response and then feel broken when it keeps firing. The page offers a different stance: the nervous system as a guard dog who learned to bark at everything because once the barking mattered. You do not scold a loyal dog; you let it know you heard it, check the yard, and tell it the job is done for now. The client writes what sets their dog barking, how they usually respond, and what it would sound like to thank the dog and check the yard. The page stays in the present and never asks about the original reason for the barking.', '[{"id": "f0", "type": "textarea", "label": "What sets my guard dog barking in an ordinary week:"}, {"id": "f1", "type": "textarea", "label": "How I usually respond to the barking (fight it, hide from it, feel ashamed):"}, {"id": "f2", "type": "textarea", "label": "What I could say to the dog instead, in words that sound like me:"}, {"id": "f3", "type": "textarea", "label": "What checking the yard looks like for me (looking around, naming the room, feeling my feet):"}, {"id": "f4", "type": "textarea", "label": "One barking moment this week where I will try thanking the dog first:"}, {"id": "f5", "type": "textarea", "label": "What I notice about the dog when I stop fighting it:"}]'::jsonb, array['PTSD and trauma', 'metaphor', 'acceptance']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('tipp-cold-water-on-the-wrists-at-a-reminder-card', 'TIPP Cold Water on the Wrists at a Reminder Card', 'dbt'::resource_kind, 'A TIPP temperature card for running cold water over the wrists when a reminder spikes the body, with the steps and a log.', 'Use it to give a client one fast, portable body skill for the moment a reminder hits in a public place.', array['Adults', 'Teens']::text[], 'Two minutes, as needed', 'Cold water on the wrists and face is the most portable piece of TIPP, available in any restroom and most kitchens. The card sets the steps: notice the spike, find a sink, run cold water over both wrists for thirty seconds to a minute, breathe out longer than in, then name three things in the room. Then it logs each use: where, what the body did before, what it did after. Rehearse it once in session at a sink. It is a stabilizer, not a fix; the point is to come down enough to choose the next step. A client with a heart condition should check with their physician about cold exposure.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what the reminder was (no details needed, just the cue):"}, {"id": "f1", "type": "textarea", "label": "What my body was doing before the cold water (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "The steps I used: how long, wrists or face, and the breath afterward:"}, {"id": "f3", "type": "textarea", "label": "What my body was doing after (0 to 10), and the three things I named in the room:"}, {"id": "f4", "type": "textarea", "label": "The sinks I can reach in my usual week (work, school, store, home):"}, {"id": "f5", "type": "textarea", "label": "What I did next, once I had come down enough to choose:"}]'::jsonb, array['PTSD and trauma', 'TIPP', 'grounding']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('nightmare-wake-up-shared-bed-plan-for-partners', 'Nightmare Wake-Up Shared Bed Plan for Partners', 'couples'::resource_kind, 'A plan for the partner of someone who wakes from nightmares: what to do, what not to do, and what each needs afterward.', 'Use it to give both partners a rehearsed response to a nightmare at three in the morning instead of improvising while frightened.', array['Couples']::text[], '30 minutes, in session', 'Nightmares in a shared bed frighten both people, and partners often do the wrong helpful thing: grabbing, shaking, asking what the dream was. The plan is made calmly in daylight. The client who has the nightmares writes what helps (a light on, their name said softly, space, a hand only when asked) and what makes it worse. The partner writes what the wake-ups are like for them and what they need afterward. Together they set the steps, a phrase for I am back, and how the next morning is handled. No part of the plan asks about the content of the dreams.', '[{"id": "f0", "type": "textarea", "label": "For the partner who has the nightmares: what helps me when I wake, and what makes it worse:"}, {"id": "f1", "type": "textarea", "label": "For the partner who has the nightmares: how I want to be touched or not touched in those first minutes:"}, {"id": "f2", "type": "textarea", "label": "For the other partner: what the wake-ups are like for me, and what I need afterward:"}, {"id": "f3", "type": "textarea", "label": "Our steps, in order, from the first sound to both of us settled again:"}, {"id": "f4", "type": "textarea", "label": "The phrase that means I am back and the phrase that means I need a minute:"}, {"id": "f5", "type": "textarea", "label": "How we will handle the next morning, and what we will not ask each other:"}]'::jsonb, array['PTSD and trauma', 'sleep', 'support']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('sent-email-reread-count-log-sheet', 'Sent Email Reread Count Log Sheet', 'worksheet'::resource_kind, 'A log of how many times the client rereads an email after sending it, and what the rereading is looking for.', 'Use it to make a hidden checking habit visible and to show the client what the reread never finds.', array['Adults']::text[], 'One week', 'Post-send rereading is a checking behavior clients rarely report because it feels like diligence. The log counts: each email that mattered, how many times the client opened the sent copy, what they were looking for, and what they found. By midweek most see the pattern: the search is for proof they did not offend, and the proof never arrives because the reply has not. The sheet ends with a delay experiment: one email the client agrees not to reread until the reply comes. Pair it with a thought record if a particular email takes over the week.', '[{"id": "f0", "type": "textarea", "label": "The emails I sent this week that I went back to reread:"}, {"id": "f1", "type": "textarea", "label": "For each: how many times I opened the sent copy, and when:"}, {"id": "f2", "type": "textarea", "label": "What I was looking for each time, honestly:"}, {"id": "f3", "type": "textarea", "label": "What I actually found, and what happened to the anxiety after each reread:"}, {"id": "f4", "type": "textarea", "label": "One email I will not reread until the reply arrives, and what I will do with the urge:"}, {"id": "f5", "type": "textarea", "label": "End of the week: what the log showed me about the habit:"}]'::jsonb, array['anxiety', 'checking', 'self-monitoring']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('odd-engine-noise-probability-estimate-sheet', 'Odd Engine Noise Probability Estimate Sheet', 'cbt'::resource_kind, 'A probability sheet for a strange noise from the car, the house or the body that the client''s mind reads as imminent disaster.', 'Use it to practice estimating how likely the feared outcome really is instead of treating the first thought as the forecast.', array['Adults']::text[], '15 minutes', 'A new noise from the engine is a good training case for probability overestimation: the fear is about breakdown, cost and being stranded, and the actual range of causes is wide. The client writes the noise, the feared outcome, and the odds their gut gives it. Then they list every cause they can think of from harmless to serious, give each a rough likelihood, and compare the sum with the gut number. Then comes the practical line: what a reasonable person would do this week, which is usually to have it looked at and drive on. Use the same sheet for odd sensations and odd emails.', '[{"id": "f0", "type": "textarea", "label": "The noise or sign, and when I first noticed it:"}, {"id": "f1", "type": "textarea", "label": "The outcome my mind jumped to, and the odds my gut gives it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "Every possible cause I can think of, from harmless to serious:"}, {"id": "f3", "type": "textarea", "label": "A rough likelihood for each cause, so the list adds up to something near 100:"}, {"id": "f4", "type": "textarea", "label": "The gut number compared with the list: what the gap tells me:"}, {"id": "f5", "type": "textarea", "label": "What a reasonable person would do this week about the noise, and when I will do it:"}]'::jsonb, array['anxiety', 'probability', 'catastrophizing']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('anxious-mind-as-a-hovering-waiter-page', 'Anxious Mind as a Hovering Waiter Page', 'act'::resource_kind, 'A defusion page that pictures the anxious mind as a waiter who keeps returning to ask whether everything is all right.', 'Use it to help a client acknowledge the mind''s constant check-ins without answering every one.', array['Adults', 'Teens']::text[], '15 minutes', 'Anxious clients recognize the hovering waiter: well-meaning, constant, back every two minutes to ask if everything is okay, until the meal cannot be eaten. The page asks the client to write a typical hour of the mind''s check-ins in that voice, then to practice the response a diner gives: a nod, a thank you, and back to the conversation. Not sending the waiter away, not ordering something new each time. The last lines ask the client to pick one hour this week to eat the meal while the waiter hovers.', '[{"id": "f0", "type": "textarea", "label": "An hour of my mind''s check-ins, written as a waiter''s questions:"}, {"id": "f1", "type": "textarea", "label": "What I usually do when the waiter comes back (answer at length, order something new, snap):"}, {"id": "f2", "type": "textarea", "label": "The short nod I will give instead, in words that fit me:"}, {"id": "f3", "type": "textarea", "label": "The meal I am trying to eat (the conversation, task or rest the check-ins keep interrupting):"}, {"id": "f4", "type": "textarea", "label": "One hour this week when I will keep eating while the waiter hovers:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the waiter when I stopped answering in full:"}]'::jsonb, array['anxiety', 'defusion', 'metaphor']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('paced-breathing-before-opening-the-lab-portal-card', 'Paced Breathing Before Opening the Lab Portal Card', 'dbt'::resource_kind, 'A paced breathing card for the moment a test result notification arrives and the client''s thumb hovers over the link.', 'Use it to put sixty seconds of slowed breathing between the notification and the opening, so the client reads it steadier.', array['Adults']::text[], 'Two minutes, as needed', 'The ping that results are ready is a sharp spike for many clients, and the result gets read through the spike. The card asks for one minute of paced breathing first: in for four, out for six, six rounds, feet on the floor, phone face down. Then a single question before opening: what will I do in the next hour whichever way it reads. Then open it. The log records the spike before and after the breathing and what the client did with the hour. The card does not stop the client opening results; it changes the state they open them in.', '[{"id": "f0", "type": "textarea", "label": "The notification I am waiting for, and what my body does when a ping arrives:"}, {"id": "f1", "type": "textarea", "label": "Before the breathing: my level (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "Six rounds of in for four, out for six, phone face down. After: my level (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "What I will do in the next hour if the result is fine, and if it is not:"}, {"id": "f4", "type": "textarea", "label": "What the result said, and what I actually did with the hour:"}, {"id": "f5", "type": "textarea", "label": "What the minute of breathing changed about how I read it:"}]'::jsonb, array['anxiety', 'paced breathing', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('worst-case-best-case-likely-case-spin-game', 'Worst Case Best Case Likely Case Spin Game', 'game'::resource_kind, 'A group game where a spinner picks worst, best or likely case and players finish a worry scenario in that register.', 'Use it to get a group practicing the three-case move on real worries while taking turns and laughing at the extremes.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Rules: players write a current worry on a slip, anonymously if they prefer. On each turn a player draws a slip, spins a spinner marked worst, best and likely, and tells the ending of the worry in that case in under a minute. The group then votes on whether the likely case was really likely. Each slip is played until all three cases have been spun for it. Every player takes at least two turns. Debrief: how it felt to hear a worst case out loud, how often the likely case had never been considered by the worrier, and how to spin all three alone when a worry arrives midweek.', '[{"id": "f0", "type": "textarea", "label": "The worry I put in, and the three endings the group gave it:"}, {"id": "f1", "type": "textarea", "label": "Which case I usually live in, and how it felt to hear the other two:"}, {"id": "f2", "type": "textarea", "label": "A worst case that sounded ridiculous once it was said out loud:"}, {"id": "f3", "type": "textarea", "label": "A likely case that I had honestly never considered:"}, {"id": "f4", "type": "textarea", "label": "How I will spin all three cases on my own the next time a worry arrives:"}]'::jsonb, array['anxiety', 'group game', 'decatastrophizing']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('text-back-one-friend-today-micro-goal-sheet', 'Text Back One Friend Today Micro Goal Sheet', 'worksheet'::resource_kind, 'A sheet for a client whose unanswered messages have piled up, picking one person to text back today and nothing more.', 'Use it to break the frozen inbox with a single reply instead of waiting for the energy to answer everyone.', array['Adults', 'Teens']::text[], '10 minutes daily for a week', 'Low mood turns a few unanswered texts into a wall the client cannot face, and the longer the silence the heavier the guilt. The sheet lists the people waiting, asks the client to pick the one who would be easiest or who matters most today, and gives the message a shape: one honest line about the quiet, one line about them. Send it, then record what came back. One a day for a week. Do not let the client plan to clear the whole list; the sheet is one person, and the list may stay long. Watch for apology spirals in the draft and trim them.', '[{"id": "f0", "type": "textarea", "label": "The people I have not replied to, and roughly how long each has been waiting:"}, {"id": "f1", "type": "textarea", "label": "The one I will text today, and why them:"}, {"id": "f2", "type": "textarea", "label": "My message, in two lines: one about the quiet, one about them:"}, {"id": "f3", "type": "textarea", "label": "What came back, and how I felt reading it:"}, {"id": "f4", "type": "textarea", "label": "Tomorrow''s one person:"}, {"id": "f5", "type": "textarea", "label": "End of the week: how many I reached, and what happened to the wall:"}]'::jsonb, array['depression', 'behavioral activation', 'connection']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('i-let-everyone-down-this-week-evidence-sheet', 'I Let Everyone Down This Week Evidence Sheet', 'cbt'::resource_kind, 'An evidence sheet for the Sunday verdict that the client failed everyone this week, tested against what actually happened.', 'Use it to put a global self-judgment next to the week''s actual record and let the client compare the two.', array['Adults', 'Teens']::text[], '20 minutes', 'The end of a low week often arrives with a verdict: I let everyone down. The sheet treats the verdict as a claim and asks for the record. Who exactly, let down how, and what the client did for anyone this week, including the small things low mood hides (showing up, replying, feeding the cat). Then the client weighs both columns and writes a sentence that fits all the evidence. Expect the first pass of the for column to be empty; ask about each day in turn. Use it weekly for a few weeks so the client learns to run it alone.', '[{"id": "f0", "type": "textarea", "label": "The verdict, in the exact words my mind uses:"}, {"id": "f1", "type": "textarea", "label": "Who I believe I let down, and how, one at a time:"}, {"id": "f2", "type": "textarea", "label": "Evidence for the verdict: what I actually did or did not do:"}, {"id": "f3", "type": "textarea", "label": "Evidence against it: every small thing I did for anyone this week, day by day:"}, {"id": "f4", "type": "textarea", "label": "A sentence that fits both columns, without the word everyone:"}, {"id": "f5", "type": "textarea", "label": "How much I believe the verdict now (0 to 100), compared with when I started:"}]'::jsonb, array['depression', 'evidence', 'self-criticism']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('low-mood-fog-driving-with-headlights-on-page', 'Low Mood Fog Driving With Headlights On Page', 'act'::resource_kind, 'A committed action page that treats a foggy low day like driving in fog: slower, headlights on, one stretch of road at a time.', 'Use it to help a client keep moving through a flat day without waiting for the fog to lift first.', array['Adults']::text[], '15 minutes', 'Clients in a low stretch often stop until the mood clears, as if waiting for the fog to lift before driving. The page offers the other way: you do not drive fast in fog, but you do drive, with headlights on and attention on the next few yards. The client names what their fog is like today, picks the one stretch of road that is visible (the next hour, the next task), and turns on the headlights (a value, a person, a reason). The page does not promise clearing weather. It asks for the next stretch at fog speed.', '[{"id": "f0", "type": "textarea", "label": "What the fog is like today, in a few words:"}, {"id": "f1", "type": "textarea", "label": "The speed I am trying to drive at, compared with the speed the fog allows:"}, {"id": "f2", "type": "textarea", "label": "The one stretch of road I can see: the next hour or the next task:"}, {"id": "f3", "type": "textarea", "label": "My headlights: the value or person that lights that stretch:"}, {"id": "f4", "type": "textarea", "label": "What I did in that stretch, at fog speed:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the fog after driving a little way into it:"}]'::jsonb, array['depression', 'committed action', 'metaphor']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('accumulating-positives-weekend-calendar-card', 'Accumulating Positives Weekend Calendar Card', 'dbt'::resource_kind, 'An accumulating positives card that plans two small pleasant events into an otherwise empty weekend and records how they went.', 'Use it to put something on a weekend that would otherwise be two blank days, chosen for pleasure rather than productivity.', array['Adults', 'Teens']::text[], '15 minutes on Friday, used over the weekend', 'Empty weekends are hard for a client in a low stretch; Saturday and Sunday become one long gray stretch of bed and scrolling. The card plans two short pleasant events, one per day, from the DBT accumulating positives list or the client''s own: a walk to a particular bench, a call, a bakery, a record played all the way through. Each is given a time. The client does them whether or not they feel like it and rates the mood before and after. Keep the events small enough to survive a bad morning. Review Monday what got done and what the ratings showed.', '[{"id": "f0", "type": "textarea", "label": "Saturday''s pleasant event, the time it will happen, and what it needs (shoes, a person, money):"}, {"id": "f1", "type": "textarea", "label": "Sunday''s pleasant event, the time, and what it needs:"}, {"id": "f2", "type": "textarea", "label": "The thought that will try to cancel each one, written in advance:"}, {"id": "f3", "type": "textarea", "label": "Saturday: mood before (0 to 10), mood after, and what actually happened:"}, {"id": "f4", "type": "textarea", "label": "Sunday: mood before (0 to 10), mood after, and what actually happened:"}, {"id": "f5", "type": "textarea", "label": "Next weekend''s two events, picked while the memory of this one is fresh:"}]'::jsonb, array['depression', 'accumulating positives', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('asking-how-are-you-really-script-for-partners', 'Asking How Are You Really Script for Partners', 'couples'::resource_kind, 'A script for the partner of someone in a low stretch to ask how they really are, and for the other to answer without a performance.', 'Use it to give partners words for the check-in that keeps getting skipped because neither knows how to start it.', array['Couples']::text[], '25 minutes', 'When one partner is low, the other often asks how are you in a tone that wants a fine, and gets one. The sheet builds a better check-in from both sides: the asking partner writes when and how they will ask (sitting down, phone away), and the low partner writes how they want to be asked and what they can honestly say on a bad day. They agree on a few words that stand in for a long explanation, and on what the asking partner does with a hard answer (stay, not fix). If the answers touch thoughts of not wanting to be here, the plan names 988, call or text, and the next step together.', '[{"id": "f0", "type": "textarea", "label": "For the asking partner: how I usually ask, and what I actually want to hear:"}, {"id": "f1", "type": "textarea", "label": "For the low partner: how I want to be asked, and when it is easiest to answer honestly:"}, {"id": "f2", "type": "textarea", "label": "Our shorthand for a hard day (a number, a color, a few words) so I do not have to explain:"}, {"id": "f3", "type": "textarea", "label": "For the asking partner: what I will do with a hard answer, instead of fixing or arguing:"}, {"id": "f4", "type": "textarea", "label": "If the answer includes not wanting to be here: we call or text 988 together, and the step we take next:"}, {"id": "f5", "type": "textarea", "label": "When we will check in this week, and how it went:"}]'::jsonb, array['depression', 'support', 'communication']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('expired-food-in-the-fridge-weekly-sweep-sheet', 'Expired Food in the Fridge Weekly Sweep Sheet', 'worksheet'::resource_kind, 'A ten minute weekly sweep for the fridge, for a client whose forgotten groceries have become a source of shame and waste.', 'Use it to replace guilt about spoiled food with a short, timed routine that fits an attention that wanders.', array['Adults']::text[], 'Ten minutes weekly', 'Forgotten groceries are a common and quietly painful pattern for a client with a wandering attention: the good intentions in the produce drawer become a weekly reminder of failure. The sheet sets a ten-minute sweep on a fixed day with a timer: top shelf to bottom, out with anything gone, a note of what was bought and never used. Over a few weeks the note shows what not to buy again. The routine is the point, not a clean fridge. Pair it with a visible cue (the timer on the fridge door) and keep the day attached to something that already happens, like trash night.', '[{"id": "f0", "type": "textarea", "label": "The day and time of my weekly sweep, and the thing it is attached to that already happens:"}, {"id": "f1", "type": "textarea", "label": "This week: what I threw out, and what I bought and never used:"}, {"id": "f2", "type": "textarea", "label": "The thought that showed up while I did it, and what I said back:"}, {"id": "f3", "type": "textarea", "label": "A pattern I am starting to see in what goes uneaten:"}, {"id": "f4", "type": "textarea", "label": "One thing I will not buy next week because of the pattern:"}, {"id": "f5", "type": "textarea", "label": "After four sweeps: what changed in the fridge and in how I feel opening it:"}]'::jsonb, array['ADHD', 'routine', 'executive function']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('i-need-the-perfect-planner-before-i-start-belief-sheet', 'I Need the Perfect Planner Before I Start Belief Sheet', 'cbt'::resource_kind, 'A belief sheet for the client who keeps buying systems and apps instead of starting, convinced the right one will fix everything.', 'Use it to look at the belief that the tool comes first and to get one task started with whatever the client already owns.', array['Adults', 'Teens']::text[], '20 minutes', 'A client with a drawer of unused planners and a phone full of task apps is often running a belief: once I find the right system, I will be organized. The sheet writes the belief out, lists the systems tried and how long each lasted, and asks what the search itself does for the client (hope, a fresh start, a reason not to begin yet). Then it tests the belief with one task started today using a sticky note. Keep the tone warm; the search is understandable. The question is whether it is working.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my own words (once I have the right system, I will…):"}, {"id": "f1", "type": "textarea", "label": "Every system or app I have tried, and roughly how long each lasted:"}, {"id": "f2", "type": "textarea", "label": "What the search for a new system gives me, honestly:"}, {"id": "f3", "type": "textarea", "label": "What it costs me, in money, time and tasks not started:"}, {"id": "f4", "type": "textarea", "label": "One task I will start today with a sticky note and nothing else:"}, {"id": "f5", "type": "textarea", "label": "What happened, and what it says about the belief:"}]'::jsonb, array['ADHD', 'core beliefs', 'task initiation']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('hyperfocus-hour-noticing-and-exit-page', 'Hyperfocus Hour Noticing and Exit Page', 'act'::resource_kind, 'A present-moment page for noticing when the client has fallen into a long focus tunnel and choosing when to come out.', 'Use it to help a client who loses hours to one thing build a gentle check-in and a chosen exit rather than a crash.', array['Adults', 'Teens']::text[], '15 minutes, then used daily', 'Deep focus can be a gift and a trap: the client surfaces four hours later, hungry, late and guilty. The page is not about stopping the focus but about noticing it from the inside. The client names the things that tend to pull them under, the signs that they are under (time disappearing, ignoring the body), and a small anchor that can reach them there (an alarm with a kind label, a glass of water on the desk). Then they choose the exit in advance: at this time, for this reason, whether or not the thing is finished. The exit is a value choice, not a punishment.', '[{"id": "f0", "type": "textarea", "label": "The things that pull me into a focus tunnel, and how often it happens in a week:"}, {"id": "f1", "type": "textarea", "label": "The signs from inside the tunnel that I am under (what my body and the clock do):"}, {"id": "f2", "type": "textarea", "label": "What usually brings me out, and what state I am in when it does:"}, {"id": "f3", "type": "textarea", "label": "An anchor that could reach me gently in there (an alarm, a label, a person, water):"}, {"id": "f4", "type": "textarea", "label": "Today''s chosen exit: the time, the reason, and what I will do first when I surface:"}, {"id": "f5", "type": "textarea", "label": "After a week: what noticing the tunnel changed, if anything:"}]'::jsonb, array['ADHD', 'present moment', 'attention']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('stop-skill-before-interrupting-in-the-meeting-card', 'STOP Skill Before Interrupting in the Meeting Card', 'dbt'::resource_kind, 'A STOP card for the moment an idea arrives mid-meeting and the client is about to talk over whoever is speaking.', 'Use it to put a half-second of stop between the impulse to interrupt and the mouth opening, with a place to park the idea.', array['Adults']::text[], 'Ten minutes to set up, used in meetings', 'Interrupting is rarely rudeness in a client whose thoughts arrive fast and leave faster; it is fear of losing the idea. STOP (Stop, Take a step back, Observe, Proceed mindfully) fits if the idea has somewhere to go. The card pairs the skill with a parking spot: a notepad line or a phone note where the thought waits. Stop, write the one word that will bring it back, observe who is speaking and whether they are finished, then proceed, either by speaking or by letting it go. Log the meetings. The client is often surprised by how many parked ideas were not needed.', '[{"id": "f0", "type": "textarea", "label": "The meetings where I interrupt most, and what it costs me there:"}, {"id": "f1", "type": "textarea", "label": "My parking spot for ideas (notepad, phone note, a word on my hand):"}, {"id": "f2", "type": "textarea", "label": "Stop: what I will do with my body in the half second (close mouth, breathe out, hands still):"}, {"id": "f3", "type": "textarea", "label": "Observe: what I will look for before speaking (is the speaker finished, is the idea still needed):"}, {"id": "f4", "type": "textarea", "label": "This week''s log: how many times I stopped, how many ideas I parked, how many I used:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the parked ideas by the end of the week:"}]'::jsonb, array['ADHD', 'STOP', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('beat-the-song-tidy-up-dance-play', 'Beat the Song Tidy Up Dance Play', 'kids'::resource_kind, 'A tidy-up play where a child races to clear a space before a favorite song ends, with the parent dancing and picking up alongside.', 'Use it to turn a stalled cleanup into a short, moving, musical sprint a child with a restless attention can finish.', array['Children']::text[], 'One song, daily or as needed', 'A room to tidy is an impossible task for a child who cannot see where to start; one song is a task with an end. The parent picks the child''s favorite song, names the one zone to clear (the floor, not the room), and starts the music. Both dance and pick up until the song ends; whatever is done is done. The parent''s job is to move too, keep it silly, and never extend the task past the song. Over days the zone can grow. Debrief with one question: what helped you keep going?', '[{"id": "f0", "type": "textarea", "label": "The song we pick, and the one zone we clear before it ends:"}, {"id": "f1", "type": "textarea", "label": "What my grown-up does while the song plays:"}, {"id": "f2", "type": "textarea", "label": "How much was done when the music stopped, and how that felt:"}, {"id": "f3", "type": "textarea", "label": "The part that was the most fun, and the part that was hardest:"}, {"id": "f4", "type": "textarea", "label": "For my grown-up: how I kept it to one zone and one song, and what I will try tomorrow:"}]'::jsonb, array['ADHD', 'kids', 'task initiation']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('airport-layover-bar-urge-plan-sheet', 'Airport Layover Bar Urge Plan Sheet', 'worksheet'::resource_kind, 'A plan for a long layover, where the bar is the only open seat and the urge to use arrives with the boredom.', 'Use it to give a client a worked-out plan for the hours in a terminal before they are standing in front of the bar.', array['Adults']::text[], '20 minutes, before the trip', 'A layover is a setup: hours to fill, nowhere comfortable to sit, no one who knows the client, and a bar every fifty feet. The sheet plans the hours before the trip: where the client will sit (gates, lounges, a quiet corner), what they will eat, who they will text when they land, what they will do with their hands, and the line they will use if a stranger offers a drink. It also plans for the urge arriving anyway: the skill, the walk, the call. Review the sheet on the other side of the trip and keep what worked for the next one.', '[{"id": "f0", "type": "textarea", "label": "The trip, the layover length, and the airports:"}, {"id": "f1", "type": "textarea", "label": "Where I will sit and spend the hours, with the bar out of my eyeline:"}, {"id": "f2", "type": "textarea", "label": "What I will eat and drink, and when:"}, {"id": "f3", "type": "textarea", "label": "Who I will text or call during the layover, and what I will do with my hands:"}, {"id": "f4", "type": "textarea", "label": "If the urge arrives anyway: the skill, the walk, the call, in order:"}, {"id": "f5", "type": "textarea", "label": "After the trip: what worked, what did not, and what I would change:"}]'::jsonb, array['addiction', 'substance use', 'planning']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('everyone-at-the-reunion-will-be-drinking-prediction-sheet', 'Everyone at the Reunion Will Be Drinking Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for a reunion or old-friends gathering the client expects to be all drinking and all questions.', 'Use it to test the client''s forecast of a social event against what actually happens there.', array['Adults']::text[], '20 minutes before, 15 after', 'Old friends gatherings carry a specific forecast for a client who has changed their substance use: everyone will drink, everyone will notice, everyone will ask. The sheet writes the predictions in detail, with odds, before the event: how many people will be drinking, how many will comment, what will be said, how the client will feel at the hour mark. Afterward the client records what happened. Most find the commenting far rarer than predicted and the feeling at the hour mark different from the forecast. Pair it with an exit plan so the experiment is safe either way.', '[{"id": "f0", "type": "textarea", "label": "The event, who will be there, and what I predict about the drinking (how many, how much):"}, {"id": "f1", "type": "textarea", "label": "What I predict people will say to me about not using, and how many will say it:"}, {"id": "f2", "type": "textarea", "label": "How I predict I will feel at the one hour mark (0 to 10), and what I will want to do:"}, {"id": "f3", "type": "textarea", "label": "My exit plan and my ride, written before I go:"}, {"id": "f4", "type": "textarea", "label": "After: what actually happened on each prediction:"}, {"id": "f5", "type": "textarea", "label": "What the gap between forecast and event tells me for the next gathering:"}]'::jsonb, array['addiction', 'predictions', 'substance use']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('mind-s-bargaining-table-noticing-page', 'Mind''s Bargaining Table Noticing Page', 'act'::resource_kind, 'A defusion page for the mind''s negotiations before using: just one, only tonight, you earned it, laid out as offers on a table.', 'Use it to help a client see the bargaining as a predictable set of moves rather than a reason to act.', array['Adults']::text[], '15 minutes', 'Before a return to use, the mind usually sits the client down at a bargaining table and makes offers, and the offers are remarkably consistent. The page asks the client to write them all out as a negotiator would: the opening offer, the concession, the flattery, the deadline. Seeing them on paper, most clients recognize the script. The move is to notice an offer arriving (there is the one about having earned it), name it, and leave the table without countering. Countering is still negotiating. End with one place the client will go instead when the table is set.', '[{"id": "f0", "type": "textarea", "label": "The offers my mind makes before I use, written as a negotiator''s lines:"}, {"id": "f1", "type": "textarea", "label": "The one that works on me most often, and why it lands:"}, {"id": "f2", "type": "textarea", "label": "What happens when I try to argue with the offers:"}, {"id": "f3", "type": "textarea", "label": "The name I will give each offer when it arrives (the earned-it one, the just-one one):"}, {"id": "f4", "type": "textarea", "label": "Where I will go and what I will do instead of sitting down at the table:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the offers after a week of naming them:"}]'::jsonb, array['addiction', 'defusion', 'urges']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('adaptive-denial-just-not-this-hour-card', 'Adaptive Denial Just Not This Hour Card', 'dbt'::resource_kind, 'An adaptive denial card for telling an urge not now, just not this hour, and planning what fills the hour instead.', 'Use it to give a client a way to put off using one hour at a time without having to win the whole argument tonight.', array['Adults']::text[], 'Ten minutes, then one hour at a time', 'Adaptive denial is the DBT move of telling an urge not never, just not right now, because never is too big to hold when the urge is loud. The card makes the hour concrete: the client writes what they will do for the next sixty minutes, who they could call, and the time at which they will decide again. Then they decide again. The log records each hour and what the urge did across them. Most urges do not survive two hours of the card. Combine it with a safety plan if the client''s use has been dangerous, and name 988 (call or text) on the card for a night that turns dark.', '[{"id": "f0", "type": "textarea", "label": "The urge, and what it wants me to do right now (0 to 10):"}, {"id": "f1", "type": "textarea", "label": "Not this hour. What I will do for the next sixty minutes instead:"}, {"id": "f2", "type": "textarea", "label": "Who I could call or text in this hour, with the number written here:"}, {"id": "f3", "type": "textarea", "label": "The time I will decide again, and what the urge was at that time (0 to 10):"}, {"id": "f4", "type": "textarea", "label": "Hour two, if needed: what I did, and the urge at the end:"}, {"id": "f5", "type": "textarea", "label": "If the night turns dark or I think about ending it: call or text 988, and tell the person above."}]'::jsonb, array['addiction', 'urges', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('substance-free-date-night-ideas-list-for-partners', 'Substance-Free Date Night Ideas List for Partners', 'couples'::resource_kind, 'A list partners build together of date nights that do not revolve around a drink, with each partner adding ideas and vetoes.', 'Use it to give a couple whose dates used to center on substances a new menu they both actually want.', array['Couples']::text[], '30 minutes', 'When one or both partners change their substance use, the old date nights go with it, and the couple often stops dating rather than rethinking it. The sheet has each partner list ten things they would enjoy doing together without a drink, then compare and star the overlaps. Each gets two vetoes. The partner who has changed their use names the places and times that are harder, and the other writes what support looks like on a date (not ordering wine, leaving early without a fuss). Then they book the first one. Keep the list growing over months.', '[{"id": "f0", "type": "textarea", "label": "Partner A: ten date ideas I would genuinely enjoy with no substance involved:"}, {"id": "f1", "type": "textarea", "label": "Partner B: ten date ideas I would genuinely enjoy with no substance involved:"}, {"id": "f2", "type": "textarea", "label": "The overlaps we starred, and each of our two vetoes:"}, {"id": "f3", "type": "textarea", "label": "For the partner who has changed their use: the places and times that are harder, and what helps:"}, {"id": "f4", "type": "textarea", "label": "For the other partner: what support on a date looks like from me, concretely:"}, {"id": "f5", "type": "textarea", "label": "Our first date from the list, booked for this date and time:"}]'::jsonb, array['addiction', 'connection', 'substance use']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('customer-service-hold-music-frustration-log-sheet', 'Customer Service Hold Music Frustration Log Sheet', 'worksheet'::resource_kind, 'A log of anger rising during long holds and automated phone menus, with what the client does at each minute mark.', 'Use it to catch anger escalating in a situation with no one to blame yet, before the human finally picks up.', array['Adults']::text[], 'One week', 'Phone holds are an anger laboratory: the frustration builds with no target, and the first human to answer gets all of it. The log tracks each call this week: the wait, the body at five, ten and fifteen minutes, the thoughts (they do this on purpose, I am being ignored), and what the client did while waiting. Then it records the first sentence the client said to the person who answered. Most see the escalation clearly and can plan for it: speaker on, hands busy, a prepared opening line. Use it as a low-stakes rehearsal for the higher-stakes flashpoints.', '[{"id": "f0", "type": "textarea", "label": "Each call this week: who I called and how long I waited:"}, {"id": "f1", "type": "textarea", "label": "My body and my thoughts at five, ten and fifteen minutes on hold:"}, {"id": "f2", "type": "textarea", "label": "What I did while waiting (paced, scrolled, stewed, something else):"}, {"id": "f3", "type": "textarea", "label": "My first sentence to the person who finally answered, word for word:"}, {"id": "f4", "type": "textarea", "label": "What I will do during the next hold: speaker on, hands busy, the opening line I will use:"}, {"id": "f5", "type": "textarea", "label": "End of the week: what the log showed me about how my anger builds:"}]'::jsonb, array['anger management', 'self-monitoring', 'de-escalation']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('being-corrected-means-being-disrespected-belief-sheet', 'Being Corrected Means Being Disrespected Belief Sheet', 'cbt'::resource_kind, 'A belief sheet for the flash of anger that comes when the client is corrected, and the rule underneath it.', 'Use it to find the rule that turns a correction into an insult and to test whether the rule holds.', array['Adults', 'Teens']::text[], '20 minutes', 'For some clients the fastest route to anger is being corrected: a coworker fixes a figure, a partner adjusts how the dishwasher is loaded, and the heat arrives before any thought. The sheet asks the client to recall a recent correction, write the rule it broke (if they correct me, they think I am stupid), and trace where the rule came from. Then it tests it: a time someone corrected them with obvious good will, a time they corrected someone without disrespect. The client writes a new rule they could try on the next correction. Watch for shame beneath the anger; it usually drives it.', '[{"id": "f0", "type": "textarea", "label": "A recent correction, what was said, and how fast the heat arrived:"}, {"id": "f1", "type": "textarea", "label": "The rule it broke, in an if-then sentence:"}, {"id": "f2", "type": "textarea", "label": "Where I think the rule came from, and who taught it to me:"}, {"id": "f3", "type": "textarea", "label": "A time I was corrected by someone who clearly meant well, and a time I corrected someone without disrespect:"}, {"id": "f4", "type": "textarea", "label": "A new rule I could try, in an if-then sentence:"}, {"id": "f5", "type": "textarea", "label": "The next correction I expect this week, and what I will do with the first three seconds:"}]'::jsonb, array['anger management', 'core beliefs', 'shame']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('anger-as-a-hot-coal-in-my-hand-page', 'Anger as a Hot Coal in My Hand Page', 'act'::resource_kind, 'An acceptance page using the hot coal image: holding a grudge to throw at someone burns the hand that holds it.', 'Use it to help a client feel the cost of carried anger and consider setting the coal down without pretending it is cool.', array['Adults', 'Teens']::text[], '15 minutes', 'The hot coal is an old image and still lands: the client is holding something hot in order to throw it, and the hand is burning while they wait for the chance. The page asks what coal the client is holding, how long, what they are waiting to do with it, and what the holding has cost (sleep, replayed conversations, a sore jaw). Setting it down is not forgiving or agreeing; it is opening the hand. The client writes what opening the hand would look like this week and what they would do with the free hand. Do not rush; some coals have been held for years.', '[{"id": "f0", "type": "textarea", "label": "The coal I am holding: who or what, and for how long:"}, {"id": "f1", "type": "textarea", "label": "What I am waiting to do with it, honestly:"}, {"id": "f2", "type": "textarea", "label": "What holding it has cost me: body, sleep, replayed scenes, time:"}, {"id": "f3", "type": "textarea", "label": "What setting it down would be, and what it would not be (not forgiving, not agreeing):"}, {"id": "f4", "type": "textarea", "label": "One small opening of the hand I could try this week:"}, {"id": "f5", "type": "textarea", "label": "What I would do with a free hand:"}]'::jsonb, array['anger management', 'acceptance', 'metaphor']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('half-smile-and-willing-hands-in-the-checkout-line-card', 'Half Smile and Willing Hands in the Checkout Line Card', 'dbt'::resource_kind, 'A half smile and willing hands card for the slow checkout line, where the body tenses and the anger builds in silence.', 'Use it to practice changing the body first in a daily, low-stakes irritation so the skill is ready for bigger ones.', array['Adults']::text[], 'Five minutes, several times a week', 'The slow line is a daily rehearsal space: the jaw sets, the arms cross, the thoughts sharpen about the person ahead. Half smile (lips slightly turned up, face relaxed) and willing hands (palms open, arms uncrossed) change the body before the thoughts have a chance. The card asks the client to use both in the next three lines they stand in, noticing tension before and after and what the mind did when the body softened. Tell the client it will feel fake at first; that is expected and not a problem. Log each line briefly.', '[{"id": "f0", "type": "textarea", "label": "The line, and my tension when I joined it (0 to 10):"}, {"id": "f1", "type": "textarea", "label": "Half smile: what my face did, and how it felt:"}, {"id": "f2", "type": "textarea", "label": "Willing hands: where my arms and hands were, and how it felt:"}, {"id": "f3", "type": "textarea", "label": "My tension after a minute of both (0 to 10), and what the thoughts did:"}, {"id": "f4", "type": "textarea", "label": "Three lines logged this week, in a few words each:"}, {"id": "f5", "type": "textarea", "label": "A bigger situation where I could use the same two moves:"}]'::jsonb, array['anger management', 'half smile', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('stomp-mat-angry-feet-then-soft-feet-play', 'Stomp Mat Angry Feet Then Soft Feet Play', 'kids'::resource_kind, 'A play where the child stomps anger out on a marked mat and then crosses to a soft spot for quiet feet, with a parent leading both halves.', 'Use it to give a child a safe place to put anger into their body and a clear way to come back down.', array['Children']::text[], '10 minutes, as needed', 'A young child''s anger lives in the feet and the fists, and telling them to calm down skips the first step. The parent marks a stomp mat (a towel, a taped square) and a soft spot (a cushion, a rug) a few steps away. Angry feet stomp on the mat, as hard as they like, while the parent counts or stomps along. When the child slows, the parent says soft feet and both walk to the cushion, where they sit, feel their feet on the floor and take three slow breaths. The parent does both halves with the child every time. Debrief with one question about what the feet needed.', '[{"id": "f0", "type": "textarea", "label": "Where our stomp mat is, and where our soft spot is:"}, {"id": "f1", "type": "textarea", "label": "How many stomps my angry feet needed today:"}, {"id": "f2", "type": "textarea", "label": "What my grown-up did on the mat with me:"}, {"id": "f3", "type": "textarea", "label": "What my feet felt like on the soft spot after three breaths:"}, {"id": "f4", "type": "textarea", "label": "For my grown-up: how I knew it was time to say soft feet, and what I will say next time:"}]'::jsonb, array['anger management', 'kids', 'self-soothing']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('counting-steps-and-even-numbers-urge-log-sheet', 'Counting Steps and Even Numbers Urge Log Sheet', 'worksheet'::resource_kind, 'A log for the quiet mental rituals of counting steps, tiles or words and needing the number to land even or right.', 'Use it to bring a hidden counting ritual into view and to track what happens when the number is left wrong on purpose.', array['Adults', 'Teens']::text[], 'One week', 'Counting rituals are often invisible even to the client''s family: steps to the door, tiles in the ceiling, syllables in a sentence, all needing to end on the right number. The log asks the client to note each counting episode this week, what had to be even or right, the discomfort if it was not, and how long the discomfort took to fade when they let the number stand. Add one small experiment: stopping on the wrong number once a day and timing the feeling. Keep the tone matter-of-fact; the client has usually never said these out loud.', '[{"id": "f0", "type": "textarea", "label": "The things I count, and the rule the number has to follow:"}, {"id": "f1", "type": "textarea", "label": "Each episode this week: where, what I counted, what the number had to be:"}, {"id": "f2", "type": "textarea", "label": "The discomfort when the number was wrong (0 to 10), and how long it took to fade:"}, {"id": "f3", "type": "textarea", "label": "Once a day: I stopped on the wrong number on purpose. What happened to the feeling, and how fast:"}, {"id": "f4", "type": "textarea", "label": "What the counting seems to be protecting against, in my own words:"}, {"id": "f5", "type": "textarea", "label": "End of the week: what the log and the experiments showed me:"}]'::jsonb, array['OCD', 'rituals', 'self-monitoring']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('if-i-do-not-cancel-the-thought-it-will-stick-belief-sheet', 'If I Do Not Cancel the Thought It Will Stick Belief Sheet', 'cbt'::resource_kind, 'A belief sheet for the rule that a bad thought must be canceled with a good one or it will stay and cause harm.', 'Use it to examine the neutralizing rule and to test what actually happens when an intrusive thought is left uncanceled.', array['Adults', 'Teens']::text[], '20 minutes, in session', 'Many clients with intrusive thoughts run a mental ritual of canceling: a bad image must be replaced with a good one, a word must be unsaid in the head, or the thought will stick and something will follow. The sheet writes the rule out, estimates belief in it, and asks what the client thinks the canceling prevents. Then it looks at the evidence: thoughts that stuck anyway despite canceling, thoughts that faded on their own, what happens to a thought when attention leaves it. Finish with one thought left uncanceled in session and a timer on how long it stays; name its category, not its content.', '[{"id": "f0", "type": "textarea", "label": "The rule, in my own words (if I do not cancel the thought, then…):"}, {"id": "f1", "type": "textarea", "label": "How much I believe it right now (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What I think the canceling prevents, specifically:"}, {"id": "f3", "type": "textarea", "label": "Thoughts that stuck even though I canceled them, and thoughts that faded though I did nothing:"}, {"id": "f4", "type": "textarea", "label": "In session: one thought left alone, and how long it stayed before attention moved:"}, {"id": "f5", "type": "textarea", "label": "What I believe about the rule now (0 to 100), and what I will try this week:"}]'::jsonb, array['OCD', 'intrusive thoughts', 'core beliefs']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('doubt-as-a-fog-machine-not-a-forecast-page', 'Doubt as a Fog Machine Not a Forecast Page', 'act'::resource_kind, 'A defusion page that pictures obsessional doubt as a fog machine making the air thick, without changing what is actually out there.', 'Use it to help a client separate the feeling of not knowing from information about danger.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients treat the feeling of doubt as a weather report: if I feel unsure the stove is off, that is information about the stove. The page offers a different image. Doubt is a fog machine at a concert, making the air thick and the shapes unclear, and saying nothing at all about the building. The client writes where the fog machine runs most, what they do when it starts (check, ask, re-walk the route), and what it would be to walk through the fog without treating it as a forecast. The fog does not have to clear before they move; it rarely does on demand.', '[{"id": "f0", "type": "textarea", "label": "Where my fog machine runs most (the stove, the lock, the email, the conversation):"}, {"id": "f1", "type": "textarea", "label": "What I do when the fog starts, and how long it lasts when I do that:"}, {"id": "f2", "type": "textarea", "label": "The difference, in my own words, between feeling unsure and something being wrong:"}, {"id": "f3", "type": "textarea", "label": "What walking through the fog without checking would look like, step by step:"}, {"id": "f4", "type": "textarea", "label": "One fog I will walk through this week, and what I will do on the other side of it:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the fog once I stopped treating it as a forecast:"}]'::jsonb, array['OCD', 'defusion', 'uncertainty']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('observe-the-itch-to-recheck-the-attachment-card', 'Observe the Itch to Recheck the Attachment Card', 'dbt'::resource_kind, 'An observe card for the moment after sending a file, when the urge rises to open the sent email and confirm the attachment is right.', 'Use it to practice watching a checking urge rise and fall in a small, daily, work-shaped moment.', array['Adults']::text[], 'Five minutes, daily for a week', 'Did I attach the right file is a checking urge most people feel and most let go; for a client caught in rechecking it opens the sent folder five times. The card asks for the observe skill at that moment: notice the urge, name it (there is the attachment urge), feel where it sits in the body, watch it for two minutes without opening the folder, and record what it did. One send a day for a week. Agree in advance what counts as a reasonable single check before sending, so the exercise is about the rechecks, not about carelessness.', '[{"id": "f0", "type": "textarea", "label": "My one reasonable check before sending, agreed in advance:"}, {"id": "f1", "type": "textarea", "label": "After sending: the urge to recheck (0 to 10), and where I feel it in my body:"}, {"id": "f2", "type": "textarea", "label": "What the urge did over two minutes of watching without opening the folder:"}, {"id": "f3", "type": "textarea", "label": "The thoughts that arrived while I watched, named as thoughts:"}, {"id": "f4", "type": "textarea", "label": "Seven days logged, in a line each: the urge at the start and the urge at two minutes:"}, {"id": "f5", "type": "textarea", "label": "What I learned about the urge by the end of the week:"}]'::jsonb, array['OCD', 'observe', 'checking']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('worry-bully-comic-strip-talk-back-craft', 'Worry Bully Comic Strip Talk Back Craft', 'kids'::resource_kind, 'A comic strip the child draws with a parent in which the worry bully makes its demand and the child''s hero answers back.', 'Use it to externalize a bossy intrusive thought for a child and give them lines for standing up to it.', array['Children']::text[], '40 minutes, then revisited', 'A child with intrusive worries and rules experiences them as a bully who must be obeyed. The comic strip gives the bully a face and the child a hero. Over four panels the parent and child draw: the bully making its demand (wash again, tap the door), the hero feeling scared, the hero answering back in the child''s own words, and what happened next when the hero did not obey. The parent draws alongside, suggests nothing for the hero''s lines, and does not help with the rituals the strip is about. Make a new strip whenever the bully finds a new demand.', '[{"id": "f0", "type": "textarea", "label": "What my worry bully looks like, and what it tells me to do:"}, {"id": "f1", "type": "textarea", "label": "Panel three: what my hero says back to the bully, in my words:"}, {"id": "f2", "type": "textarea", "label": "Panel four: what happened when my hero did not obey:"}, {"id": "f3", "type": "textarea", "label": "How scared my hero felt in panel two, and how it felt at the end (0 to 10):"}, {"id": "f4", "type": "textarea", "label": "For my grown-up: how I stayed out of the hero''s lines, and what I will do the next time the bully gives a new order:"}]'::jsonb, array['OCD', 'kids', 'externalizing']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('spinning-chair-dizziness-on-purpose-log-sheet', 'Spinning Chair Dizziness on Purpose Log Sheet', 'worksheet'::resource_kind, 'A log for bringing on dizziness deliberately in an office chair and staying with it, to get to know a feared sensation.', 'Use it to let a client meet dizziness on their own terms, in session first, so it stops arriving as a stranger.', array['Adults', 'Teens']::text[], '20 minutes, in session first', 'Dizziness is one of the sensations a client with panic fears most, and bringing it on deliberately in a safe room changes their relationship with it. Spin slowly in an office chair for thirty seconds, stop, and log: the sensation (0 to 10), the thought, what the client did, how long it took to settle. Repeat three or four times. Then the log asks what the client learned about dizziness that they did not know when it only arrived uninvited. Keep the spins gentle, check balance before standing, and skip it for anyone with an inner ear or heart condition unless their physician agrees.', '[{"id": "f0", "type": "textarea", "label": "Before the first spin: what I expect dizziness to do to me:"}, {"id": "f1", "type": "textarea", "label": "Spin one: the sensation (0 to 10), the thought that came with it, and how long it took to settle:"}, {"id": "f2", "type": "textarea", "label": "Spins two, three and four: the same three things in a line each:"}, {"id": "f3", "type": "textarea", "label": "What I did during the dizziness instead of fighting it:"}, {"id": "f4", "type": "textarea", "label": "What I know about dizziness now that I did not know when it only arrived on its own:"}, {"id": "f5", "type": "textarea", "label": "The next sensation I would be willing to meet on purpose:"}]'::jsonb, array['panic attacks', 'interoceptive', 'sensations']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('blurry-vision-means-i-am-going-blind-fact-check-sheet', 'Blurry Vision Means I Am Going Blind Fact Check Sheet', 'cbt'::resource_kind, 'A fact check for the blurring or tunneling of vision during a surge and the client''s conclusion that something is failing.', 'Use it to put the body''s explanation for blurred vision beside the client''s catastrophic one and compare them.', array['Adults', 'Teens']::text[], '15 minutes', 'Blurred or tunneled vision in a surge is frightening and poorly understood by most clients, who read it as a stroke or going blind. The sheet records the sensation, the conclusion, and how much the client believed it. Then it lays out the ordinary account: a body gearing up for action widens the pupils, shifts blood, and sharpens the center at the cost of the edges, and the blur passes as the surge does. The client compares the two accounts against what has happened every time so far. Finish with the one line they will say to themselves the next time the room goes soft at the edges.', '[{"id": "f0", "type": "textarea", "label": "The sensation, as precisely as I can describe it, and when it happens:"}, {"id": "f1", "type": "textarea", "label": "What I concluded it meant, and how strongly I believed it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The ordinary explanation, in my own words, after talking it through:"}, {"id": "f3", "type": "textarea", "label": "How many times I have had this sensation, and what has happened to my vision every time afterward:"}, {"id": "f4", "type": "textarea", "label": "How much I believe the first conclusion now (0 to 100):"}, {"id": "f5", "type": "textarea", "label": "The one line I will say to myself next time the edges go soft:"}]'::jsonb, array['panic attacks', 'fact check', 'sensations']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('panic-as-turbulence-not-a-crash-page', 'Panic as Turbulence Not a Crash Page', 'act'::resource_kind, 'An acceptance page that frames a surge as turbulence: alarming, uncomfortable, and not a sign the plane is going down.', 'Use it to help a client sit through a surge the way a seasoned flyer sits through turbulence, buckled in and waiting.', array['Adults', 'Teens']::text[], '15 minutes', 'Frequent flyers do not enjoy turbulence; they have simply stopped reading it as a crash. The page offers panic the same stance. The client writes what their turbulence feels like, what they do when it hits (grip the armrests, demand to land, watch the flight attendants), and what a seasoned flyer does instead: stays buckled, breathes, keeps reading the book, waits. Then they plan to fly through the next surge that way. The page does not say the turbulence will not come. It says the plane has landed every time, and that the client can ride the bumps without steering.', '[{"id": "f0", "type": "textarea", "label": "What my turbulence feels like, from the first bump to the worst of it:"}, {"id": "f1", "type": "textarea", "label": "What I do when it hits: grip, bolt, scan, demand to land:"}, {"id": "f2", "type": "textarea", "label": "How many flights I have been on, and how many have landed:"}, {"id": "f3", "type": "textarea", "label": "What a seasoned flyer does during the bumps, and which of those I could do:"}, {"id": "f4", "type": "textarea", "label": "The book I will keep reading through the next surge (the task, the conversation, the walk I will stay in):"}, {"id": "f5", "type": "textarea", "label": "After the next surge: what I did, and how the landing went:"}]'::jsonb, array['panic attacks', 'acceptance', 'metaphor']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('observe-and-describe-the-surge-in-three-words-card', 'Observe and Describe the Surge in Three Words Card', 'dbt'::resource_kind, 'An observe and describe card that asks for three plain words for the surge, no story, said quietly at its peak.', 'Use it to give a client a tiny, portable mindfulness move that keeps the surge a sensation and not a sentence.', array['Adults', 'Teens']::text[], 'One minute, as needed', 'At the peak of a surge there is no room for a worksheet, but there is room for three words. The card teaches observe and describe in its smallest form: notice the surge, pick three plain words for what is there (hot, fast, tight), say them quietly, and let the rest of the sentence go unspoken (and I am dying is not a word for a sensation). Practice it in session on a mild sensation first. The log collects the three words from each surge this week; over time the client notices the same few words return, which itself makes the surge more familiar.', '[{"id": "f0", "type": "textarea", "label": "Practice in session on a mild sensation: my three words:"}, {"id": "f1", "type": "textarea", "label": "Surge one this week: where I was, and my three words:"}, {"id": "f2", "type": "textarea", "label": "The sentence that tried to follow the three words, and what I did with it:"}, {"id": "f3", "type": "textarea", "label": "Surges two and three: my three words for each:"}, {"id": "f4", "type": "textarea", "label": "The words that keep coming back across surges:"}, {"id": "f5", "type": "textarea", "label": "What saying three words at the peak changed, if anything:"}]'::jsonb, array['panic attacks', 'observe', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('sensation-bingo-name-it-first-game', 'Sensation Bingo Name It First Game', 'game'::resource_kind, 'A bingo game where a caller describes body sensations in plain words and players mark them, racing to name them before the story does.', 'Use it to get a group fluent in sensation words so that a racing heart is a square on a card and not a verdict.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Rules: each player gets a bingo card of sensations (warm face, fast heart, tight chest, light head, tingling hands, dry mouth, shaky legs, blurry edges). The caller reads a short scene (a crowded room, hearing your name called) and names the sensations that might come with it; players mark any they have felt in such a moment. First to a line calls bingo and names each marked square in plain words, no interpretation allowed. Rotate the caller. Debrief: which sensations everyone had marked, how it felt to hear them read as ordinary squares, and which square each player will name first next time.', '[{"id": "f0", "type": "textarea", "label": "The squares I marked most often, and whether that surprised me:"}, {"id": "f1", "type": "textarea", "label": "A sensation I thought was only mine that half the room had marked:"}, {"id": "f2", "type": "textarea", "label": "What it was like to say the sensations out loud as plain words with no story attached:"}, {"id": "f3", "type": "textarea", "label": "The square I will name first the next time a surge begins:"}, {"id": "f4", "type": "textarea", "label": "One place this week where I will practice naming a sensation instead of explaining it:"}]'::jsonb, array['panic attacks', 'group game', 'sensations']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('bedtime-stalling-routine-map-and-response-sheet', 'Bedtime Stalling Routine Map and Response Sheet', 'worksheet'::resource_kind, 'A map of a child''s bedtime stalling moves and the parent''s planned response to each, made before the next bedtime.', 'Use it to help a parent see the stalling as a predictable sequence and meet each move calmly instead of fresh every night.', array['Adults']::text[], '25 minutes', 'Bedtime stalling (one more drink, one more question, a sudden fear, a lost toy) wears parents down because every move feels new at nine at night. The sheet maps the moves in order as they usually happen, what the parent currently does at each, and what they will do instead: a set number of trips, a scripted line, a comfort item placed in advance. The parent also writes what they will do with their own frustration at the third return. Keep the plan short enough to remember when tired, and review it after three nights rather than one.', '[{"id": "f0", "type": "textarea", "label": "The stalling moves in the order they usually happen, from lights out to finally asleep:"}, {"id": "f1", "type": "textarea", "label": "What I do now at each move, and how I feel by the third one:"}, {"id": "f2", "type": "textarea", "label": "What I will do instead at each move: the line, the limit, the comfort set up in advance:"}, {"id": "f3", "type": "textarea", "label": "What I will do with my own frustration at the third return:"}, {"id": "f4", "type": "textarea", "label": "What I will say in the morning about how bedtime went, whichever way it went:"}, {"id": "f5", "type": "textarea", "label": "After three nights: what held, what did not, and what I will adjust:"}]'::jsonb, array['parenting', 'sleep', 'routine']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('if-i-say-no-they-will-stop-loving-me-belief-sheet', 'If I Say No They Will Stop Loving Me Belief Sheet', 'cbt'::resource_kind, 'A belief sheet for the parent who cannot hold a limit because a no feels like a risk to the child''s love.', 'Use it to examine the belief that limits cost love, and to test it against what the parent has seen happen.', array['Adults']::text[], '20 minutes', 'Some parents give in not because they cannot say no but because the no feels like a wound to the relationship. The sheet writes the belief out, traces where it came from (often the parent''s own childhood), and estimates how much the parent believes it. Then the evidence: what happened the last time they held a limit, how the child behaved an hour later, and who the child runs to when hurt. The parent writes a new sentence that fits the evidence. Hold the tone warm; the belief usually sits on a real fear of being the parent they did not want to be.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my words (if I say no, then…), and how much I believe it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "Where I think the belief came from, and what no felt like in my own childhood:"}, {"id": "f2", "type": "textarea", "label": "The last time I held a limit: what my child did in the moment, and an hour later:"}, {"id": "f3", "type": "textarea", "label": "Who my child runs to when hurt or scared, and what that says:"}, {"id": "f4", "type": "textarea", "label": "A sentence about no and love that fits all the evidence:"}, {"id": "f5", "type": "textarea", "label": "The next limit I expect to hold this week, and what I will tell myself while holding it:"}]'::jsonb, array['parenting', 'core beliefs', 'limits']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('parenting-values-when-the-grandparents-disagree-page', 'Parenting Values When the Grandparents Disagree Page', 'act'::resource_kind, 'A values page for the parent caught between their own way of raising a child and a grandparent''s loud objections.', 'Use it to help a parent act from their values at the family table rather than from the wish to be approved of.', array['Adults']::text[], '20 minutes', 'Grandparents with opinions about screens, sweets, discipline and bedtimes can pull a parent off their own course, either into compliance or into a fight. The page asks the parent to name the values behind their choices, the values they can see behind the grandparent''s objections (usually love and worry), and the moments where the two collide. Then it asks what acting from the parent''s values would look like in those moments: not winning the argument, just doing the thing. The page also leaves room for one thing the grandparent might be right about.', '[{"id": "f0", "type": "textarea", "label": "The choices the grandparents object to most, and what they say:"}, {"id": "f1", "type": "textarea", "label": "The values behind my choices, in a few words each:"}, {"id": "f2", "type": "textarea", "label": "The values I can see behind their objections, even when the delivery is hard:"}, {"id": "f3", "type": "textarea", "label": "The moment this usually collides, and what I do now (comply, fight, go quiet):"}, {"id": "f4", "type": "textarea", "label": "What acting from my values would look like in that moment, without needing their approval:"}, {"id": "f5", "type": "textarea", "label": "One thing they might have a point about, and what I will do with it:"}]'::jsonb, array['parenting', 'values', 'family']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('validation-for-the-child-who-lost-the-game-card-for-parents', 'Validation for the Child Who Lost the Game Card for Parents', 'dbt'::resource_kind, 'A validation card for the minutes after a child loses a game, with the levels of validation and the lines a parent can use.', 'Use it to give a parent words that meet a child''s disappointment before trying to fix it or teach sportsmanship.', array['Adults']::text[], '10 minutes to prepare, used at game time', 'A child''s meltdown after losing a board game is a reliable test of a parent''s validation skills, and most parents go straight to it is only a game. The card walks through the DBT validation levels for that moment: full attention, reflecting back (you really wanted to win), reading the unspoken (and it felt unfair when the dice went his way), making sense of it given the child''s history, and treating the feeling as reasonable. Teaching about losing gracefully comes later, if at all. The parent writes their lines in advance and logs the next three losses.', '[{"id": "f0", "type": "textarea", "label": "What my child does after losing, and what I usually say first:"}, {"id": "f1", "type": "textarea", "label": "Reflecting back: the line I will use to say what I saw and heard:"}, {"id": "f2", "type": "textarea", "label": "Reading the unspoken: the line that names the feeling under the behavior:"}, {"id": "f3", "type": "textarea", "label": "Making sense of it: why this feeling fits for my child, given their day or their age:"}, {"id": "f4", "type": "textarea", "label": "The next three losses: what I said, and what my child did in the following five minutes:"}, {"id": "f5", "type": "textarea", "label": "When, if at all, the sportsmanship talk fits, and how I will know:"}]'::jsonb, array['parenting', 'validation', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('family-kindness-coupon-book-craft', 'Family Kindness Coupon Book Craft', 'kids'::resource_kind, 'A coupon book the child makes with a parent, each coupon a kind act the child can give to a family member to redeem.', 'Use it to give a child a concrete, playful way to practice kindness in the family and to be seen doing it.', array['Children']::text[], '40 minutes to make, used over weeks', 'A kindness coupon book turns being kind into something a child can hand over. The child and parent fold and staple a small book and fill each coupon with an act the child chooses and can actually do: one hug, help carrying groceries, reading a story to a sibling, a drawing. The child gives coupons to family members, who redeem them when they like. The parent makes a book too and gives coupons back, so kindness runs both ways. Debrief at bedtime about which coupon was redeemed and how it felt. Keep the acts small enough that the child can keep the promise.', '[{"id": "f0", "type": "textarea", "label": "The kind acts I put on my coupons, and who each one is for:"}, {"id": "f1", "type": "textarea", "label": "The first coupon someone redeemed, and what I did:"}, {"id": "f2", "type": "textarea", "label": "How it felt to give a coupon, and how it felt when it was used:"}, {"id": "f3", "type": "textarea", "label": "A coupon my grown-up gave me, and how I used it:"}, {"id": "f4", "type": "textarea", "label": "For my grown-up: how I kept the acts small and doable, and how I will redeem coupons without turning them into chores:"}]'::jsonb, array['parenting', 'kids', 'kindness']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('back-to-work-after-leave-logistics-sheet-for-new-parents', 'Back to Work After Leave Logistics Sheet for New Parents', 'worksheet'::resource_kind, 'A logistics sheet for the first weeks back at work after parental leave: pickup, pumping, backup plans and the feelings in between.', 'Use it to get the moving parts of the return to work onto paper so the new parent is not holding them all in their head at three a.m.', array['Adults']::text[], '30 minutes, the week before', 'Returning to work after parental leave is a logistical knot tied around a lot of feeling, and most new parents try to hold both without writing anything down. The sheet lays out the daily sequence (who drops off, who picks up, where pumping or feeding happens, who is called when the baby is sick), the backup for each, and the person at work who knows the situation. Then it gives the feelings their own lines: what the parent expects to feel at the drop-off and at the desk, and who they will tell. Review it after the first week and change what did not work.', '[{"id": "f0", "type": "textarea", "label": "The daily sequence: drop-off, pickup, feeding or pumping, and who does what:"}, {"id": "f1", "type": "textarea", "label": "The backup for each piece if the usual plan fails (a sick day, a late meeting):"}, {"id": "f2", "type": "textarea", "label": "The person at work who knows my situation, and what I have asked them for:"}, {"id": "f3", "type": "textarea", "label": "What I expect to feel at the first drop-off and at my desk an hour later, and who I will tell:"}, {"id": "f4", "type": "textarea", "label": "What I will do in the evening of the first day back, planned now:"}, {"id": "f5", "type": "textarea", "label": "After the first week: what worked, what did not, and what I am changing:"}]'::jsonb, array['perinatal and postpartum', 'planning', 'work']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('other-parents-would-not-have-let-that-happen-thought-record', 'Other Parents Would Not Have Let That Happen Thought Record', 'cbt'::resource_kind, 'A thought record for the moment after a small mishap with the baby when the mind declares that a better parent would have prevented it.', 'Use it to catch the comparison to an imagined perfect parent and test it against what real parents do.', array['Adults']::text[], '15 minutes', 'A bumped head, a missed nap, a diaper on backward: the mishap passes, and the thought stays. Other parents would not have let that happen. The record writes the event, the thought, the belief in it and the feeling. Then it asks who these other parents are, whether the client has ever seen one of them have a bad hour, and what a friend with a baby would say about the mishap. The client rewrites the thought to fit real parents rather than the imagined one. Keep the tone light where the client can bear it; the mishap itself is usually tiny.', '[{"id": "f0", "type": "textarea", "label": "The mishap, in one factual sentence:"}, {"id": "f1", "type": "textarea", "label": "The thought that followed, and how much I believed it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The feeling it brought, and how strong:"}, {"id": "f3", "type": "textarea", "label": "Who the other parents in the thought actually are, and whether I have ever seen one have a bad hour:"}, {"id": "f4", "type": "textarea", "label": "What a friend with a baby would say if I told them about the mishap:"}, {"id": "f5", "type": "textarea", "label": "The thought rewritten to fit real parents, and how much I believe the first version now:"}]'::jsonb, array['perinatal and postpartum', 'thought record', 'comparison']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('expecting-parent-waiting-room-comparison-page', 'Expecting Parent Waiting Room Comparison Page', 'act'::resource_kind, 'A noticing page for the comparisons the mind runs in a prenatal waiting room: who looks happier, calmer, more ready.', 'Use it to help an expecting parent notice the comparing mind at work and come back to their own chair and their own reasons.', array['Adults']::text[], '15 minutes', 'The prenatal waiting room is full of other expecting parents, and the mind sorts them instantly: that one is glowing, that couple is more together, everyone else wanted this more. The page asks the client to write the comparisons the mind made at the last visit, notice that it is the same sorting machine it runs everywhere, and practice returning: feet on the floor, the chair under them, the reason they are in the room. It ends with what the client would want to say to another parent in that room who was running the same comparisons about them.', '[{"id": "f0", "type": "textarea", "label": "The comparisons my mind ran in the waiting room at the last visit:"}, {"id": "f1", "type": "textarea", "label": "What the sorting machine concluded about me:"}, {"id": "f2", "type": "textarea", "label": "Where else the same machine runs (work, the grocery store, online):"}, {"id": "f3", "type": "textarea", "label": "My way back to my own chair: feet, seat, breath, the reason I am here:"}, {"id": "f4", "type": "textarea", "label": "What I would say to another parent in that room who was comparing themselves to me:"}, {"id": "f5", "type": "textarea", "label": "At the next visit: what the machine said, and how I came back:"}]'::jsonb, array['perinatal and postpartum', 'present moment', 'comparison']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('self-soothe-in-the-five-minutes-the-baby-sleeps-card', 'Self-Soothe in the Five Minutes the Baby Sleeps Card', 'dbt'::resource_kind, 'A self-soothe card for the short unpredictable gaps when the baby is down, with one sense-based option that takes under five minutes.', 'Use it to give a new parent something small and ready for the gaps, instead of spending them staring at the monitor or the dishes.', array['Adults']::text[], 'Five minutes, as the gaps come', 'New parents are told to rest when the baby sleeps and find that five unpredictable minutes are not enough for rest; they are enough for self-soothe. The card sets up one option per sense, each under five minutes and reachable from the couch: a scent on the wrist, a warm mug held in both hands, a song with eyes closed, a square of chocolate eaten slowly, the softest blanket on the skin. The parent picks before the gap, not during. The log records which gaps got used and how the parent felt after. The dishes are allowed to wait for one gap a day.', '[{"id": "f0", "type": "textarea", "label": "My five options, one per sense, each under five minutes and reachable from where I sit:"}, {"id": "f1", "type": "textarea", "label": "What I usually do in the gaps now (monitor, dishes, scrolling):"}, {"id": "f2", "type": "textarea", "label": "The gap I used today, which option, and how I felt before and after (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "The thought that tried to send me to the dishes, and what I said back:"}, {"id": "f4", "type": "textarea", "label": "The option that worked best this week, and the one I will drop:"}, {"id": "f5", "type": "textarea", "label": "One gap a day the dishes will wait for:"}]'::jsonb, array['perinatal and postpartum', 'self-soothe', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('feeding-decisions-without-scorekeeping-sheet-for-new-parents', 'Feeding Decisions Without Scorekeeping Sheet for New Parents', 'couples'::resource_kind, 'A sheet for partners making decisions about feeding the baby, with each partner''s worries and the rule that no one keeps score.', 'Use it to turn a loaded topic between new parents into a shared decision with both voices on paper.', array['Couples']::text[], '30 minutes', 'How the baby is fed carries pressure from relatives, the internet and each partner''s own history, and the conversation often becomes a tally of who is doing more or who gave up. The sheet asks each partner to write what they hope for, what they are afraid of, and what they have heard that is weighing on them. Then they agree on the decision for now, how long until they revisit it, who handles comments from outside, and the rule that neither keeps score of feeds or sacrifices. Medical questions go to the pediatrician; the sheet is for the two of them.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I hope for about feeding, and what I am afraid of:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I hope for about feeding, and what I am afraid of:"}, {"id": "f2", "type": "textarea", "label": "The outside voices weighing on each of us, and how much say we want them to have:"}, {"id": "f3", "type": "textarea", "label": "Our decision for now, in one sentence, and the date we will revisit it:"}, {"id": "f4", "type": "textarea", "label": "Who answers comments from relatives and friends, and the line they will use:"}, {"id": "f5", "type": "textarea", "label": "Our no-scorekeeping rule, in our own words, and what we will do when one of us slips into tallying:"}]'::jsonb, array['perinatal and postpartum', 'teamwork', 'decisions']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('taking-credit-out-loud-at-work-log-sheet', 'Taking Credit Out Loud at Work Log Sheet', 'worksheet'::resource_kind, 'A log for the client who lets credit slide past them at work, recording each chance to claim it and what they did.', 'Use it to make the pattern of deflected credit visible and to practice a plain sentence of ownership.', array['Adults']::text[], 'Two weeks', 'A client with a low opinion of themselves often gives credit away without noticing: it was a team effort, anyone could have done it, oh that was mostly Sam. The log records each chance over two weeks to own a piece of work, what the client actually said, and what it felt like. It then provides one plain sentence to practice (I did the analysis on that, and I am glad it helped) and asks the client to use it once in week two. Watch for the belief that claiming credit is bragging; the sheet has a line for the difference.', '[{"id": "f0", "type": "textarea", "label": "Each chance to take credit in week one: the situation, what I said, and how it felt:"}, {"id": "f1", "type": "textarea", "label": "The phrases I use to hand credit away, word for word:"}, {"id": "f2", "type": "textarea", "label": "The difference, in my own words, between owning my work and bragging about it:"}, {"id": "f3", "type": "textarea", "label": "My plain sentence of ownership, written and rehearsed:"}, {"id": "f4", "type": "textarea", "label": "Week two: the time I used it, what happened, and how it felt:"}, {"id": "f5", "type": "textarea", "label": "What the two weeks showed me about the pattern:"}]'::jsonb, array['self-esteem', 'assertiveness', 'work']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('i-am-only-as-good-as-my-last-mistake-belief-sheet', 'I Am Only as Good as My Last Mistake Belief Sheet', 'cbt'::resource_kind, 'A belief sheet for the client whose worth resets to zero with every error, however small.', 'Use it to find the rule that makes a mistake a verdict and to test it against the client''s whole record.', array['Adults', 'Teens']::text[], '20 minutes', 'Some clients run a scoreboard that only counts errors: a good month is wiped by one wrong email. The sheet writes the rule, estimates belief, and asks where the client learned to keep score that way. Then it gathers the evidence the rule ignores: things done well in the same week as the mistake, people who have made worse mistakes and are still respected, what the client thinks of a friend after a slip. The client rewrites the rule so that mistakes count without counting for everything. Pair it with a positive data log if the rule is well entrenched.', '[{"id": "f0", "type": "textarea", "label": "The rule, in my own words, and how much I believe it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "My most recent mistake, and what it did to my sense of my own worth that day:"}, {"id": "f2", "type": "textarea", "label": "Where I think I learned to keep score this way:"}, {"id": "f3", "type": "textarea", "label": "What I did well in the same week as the mistake:"}, {"id": "f4", "type": "textarea", "label": "Someone I respect who has made a worse mistake, and what I think of them now:"}, {"id": "f5", "type": "textarea", "label": "The rule rewritten so a mistake counts without counting for everything:"}]'::jsonb, array['self-esteem', 'core beliefs', 'perfectionism']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('mind-as-a-harsh-talent-show-judge-page', 'Mind as a Harsh Talent Show Judge Page', 'act'::resource_kind, 'A defusion page that casts the inner critic as a television talent judge: scoring, sneering, and always on air.', 'Use it to help a client hear the critic as a performance rather than a verdict and keep performing their life anyway.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients know the harsh judge from television: dramatic pauses, crushing one-liners, scores held up for the camera. The page asks the client to write a day''s self-criticism in that judge''s voice, complete with scores and catchphrases, until the critic sounds like the character it is. Then: who hired this judge, what would happen if the contestant kept singing through the verdict, and what the client wants to do this week whatever score is held up. The judge does not leave the panel. The client stops waiting for a ten before they act.', '[{"id": "f0", "type": "textarea", "label": "A day of my self-criticism, written as a talent judge''s verdicts with scores:"}, {"id": "f1", "type": "textarea", "label": "The judge''s catchphrases, the ones I hear most:"}, {"id": "f2", "type": "textarea", "label": "What I usually do when a low score is held up (stop, apologize, rehearse harder):"}, {"id": "f3", "type": "textarea", "label": "What the contestant could do instead: keep singing, finish the song, bow:"}, {"id": "f4", "type": "textarea", "label": "One thing I will do this week whatever score the judge holds up:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the judge once I heard it as a character:"}]'::jsonb, array['self-esteem', 'defusion', 'self-criticism']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('build-mastery-with-a-skill-i-am-bad-at-card', 'Build Mastery With a Skill I Am Bad At Card', 'dbt'::resource_kind, 'A build mastery card for practicing something the client is openly bad at, ten minutes a day, to feel capable through effort.', 'Use it to give a client a small daily experience of competence that does not depend on being good first.', array['Adults', 'Teens']::text[], 'Ten minutes daily for two weeks', 'Build mastery in DBT means doing something a little hard every day so the sense of capability grows. For a client with low self-worth, picking something they are already good at misses the point; picking something they are bad at and practicing anyway is the exercise. The card chooses the skill (juggling, a chord, a language app), sets ten minutes a day, and logs the attempt and the feeling after. The skill need not be mastered; the daily showing up is what builds. Watch for the client who quits on day three because they are still bad; that is the day to keep going.', '[{"id": "f0", "type": "textarea", "label": "The skill I am choosing, and how bad I am at it today:"}, {"id": "f1", "type": "textarea", "label": "The ten minutes: when and where, every day:"}, {"id": "f2", "type": "textarea", "label": "Day one to seven: a line each on what I tried and how I felt after (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "The day I most wanted to quit, and what got me to the next day:"}, {"id": "f4", "type": "textarea", "label": "Day eight to fourteen: a line each:"}, {"id": "f5", "type": "textarea", "label": "What two weeks of being bad at something on purpose did to how I see myself:"}]'::jsonb, array['self-esteem', 'build mastery', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('hidden-talent-reveal-circle-game', 'Hidden Talent Reveal Circle Game', 'game'::resource_kind, 'A circle game where each player reveals a small hidden talent or skill and the group asks three curious questions about it.', 'Use it to let group members be seen for something they are quietly good at and practice receiving interest without deflecting.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Rules: each player writes a small talent nobody in the room knows about (whistling with two fingers, folding a fitted sheet, naming every state capital) on a slip. Slips go into a bowl. On each turn the leader reads one, the group guesses whose it is, and then the owner shows or describes it and answers exactly three curious questions from the group. The owner is not allowed to downplay it; a downplay costs a point. Every player has one turn. Debrief: what it was like to be asked about, who found it hard not to shrink, and how a group can keep noticing each other''s small skills.', '[{"id": "f0", "type": "textarea", "label": "The talent I put in the bowl, and whether the group guessed me:"}, {"id": "f1", "type": "textarea", "label": "The three questions the group asked me, and the one I most enjoyed answering:"}, {"id": "f2", "type": "textarea", "label": "The moment I wanted to downplay it, and what I said instead:"}, {"id": "f3", "type": "textarea", "label": "A talent someone else revealed that I will remember them for:"}, {"id": "f4", "type": "textarea", "label": "One small skill of mine I will let someone see this week instead of hiding it:"}]'::jsonb, array['self-esteem', 'group game', 'strengths']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('saying-hello-first-in-the-hallway-steps-sheet', 'Saying Hello First in the Hallway Steps Sheet', 'worksheet'::resource_kind, 'A graded steps sheet for being the first to say hello to coworkers, neighbors or classmates in passing.', 'Use it to build a small daily approach practice in the one social moment the client meets more than any other.', array['Adults', 'Teens']::text[], 'Two weeks', 'The hallway greeting is the most frequent social moment in a client''s week and usually the most avoided: eyes down, phone up, pretending not to see. The sheet grades it: eye contact and a nod, then a hello to someone the client already knows, then to a familiar stranger, then a hello plus one line. Each day the client picks a rung, does it at least once, predicts the response and records it. Two weeks of data usually show that hellos are returned at a rate the client did not predict. Keep the rungs small; the win is saying it first.', '[{"id": "f0", "type": "textarea", "label": "The hallway, lobby or corridor where I most often avoid eye contact, and what I do instead:"}, {"id": "f1", "type": "textarea", "label": "My rungs, from a nod to a hello plus one line, in order:"}, {"id": "f2", "type": "textarea", "label": "Week one: each day''s rung, who it was, what I predicted, and what they did:"}, {"id": "f3", "type": "textarea", "label": "The response that surprised me most:"}, {"id": "f4", "type": "textarea", "label": "Week two: each day''s rung and what happened:"}, {"id": "f5", "type": "textarea", "label": "What two weeks of saying hello first showed me:"}]'::jsonb, array['social anxiety', 'hierarchy', 'behavioral']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('forgot-their-name-mid-sentence-thought-record', 'Forgot Their Name Mid-Sentence Thought Record', 'cbt'::resource_kind, 'A thought record for the moment the client blanks on someone''s name while talking to them, and what the mind concludes.', 'Use it to catch the leap from a common memory lapse to a verdict on the client as a social failure.', array['Adults', 'Teens']::text[], '15 minutes', 'Forgetting a name mid-sentence is universal and, for a socially anxious client, proof of something. The record writes the moment, the automatic thought (they could tell, they think I do not care, I am hopeless at this), the belief in it and the feeling. Then it asks how the client has felt when someone forgot their own name, what the other person was likely attending to, and what the client could have said (I am so sorry, your name has just gone out of my head). Rate the thought again at the end. It makes a good first record for a client new to the method.', '[{"id": "f0", "type": "textarea", "label": "What happened, in one factual sentence:"}, {"id": "f1", "type": "textarea", "label": "The thought that arrived, and how much I believed it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The feeling, and how strong it was:"}, {"id": "f3", "type": "textarea", "label": "A time someone forgot my name: what I thought of them, and for how long:"}, {"id": "f4", "type": "textarea", "label": "What the other person was most likely paying attention to in that moment:"}, {"id": "f5", "type": "textarea", "label": "The line I could use next time, and how much I believe the first thought now:"}]'::jsonb, array['social anxiety', 'thought record', 'mind reading']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('taking-the-shy-feeling-to-the-book-club-page', 'Taking the Shy Feeling to the Book Club Page', 'act'::resource_kind, 'A willingness page for bringing the shyness along to a book club, class or meetup instead of waiting for it to leave first.', 'Use it to help a client attend the thing they want to attend with the shy feeling in the chair beside them.', array['Adults', 'Teens']::text[], '20 minutes before, 10 after', 'Clients wait for the shyness to go before they join the group, and it never goes first. The page asks what the client wants from the book club or the class, what the shy feeling says will happen there, and what they are willing to feel in exchange for going. Then it plans the seat, the one thing they will say if asked, and the permission to be quiet otherwise. The shy feeling comes along and is given its own chair. Afterward the client writes what the feeling did during the hour and whether it needed as much attention as it demanded.', '[{"id": "f0", "type": "textarea", "label": "The group I want to join, and what I want from it:"}, {"id": "f1", "type": "textarea", "label": "What the shy feeling predicts will happen there:"}, {"id": "f2", "type": "textarea", "label": "The feelings I am willing to carry in to get what I want from the evening:"}, {"id": "f3", "type": "textarea", "label": "My plan: where I will sit, the one thing I will say if asked, and what I will not make myself do:"}, {"id": "f4", "type": "textarea", "label": "During: what the shy feeling did in its chair, and whether it stayed the whole time:"}, {"id": "f5", "type": "textarea", "label": "What I got from the hour that waiting would not have given me:"}]'::jsonb, array['social anxiety', 'willingness', 'values']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('dear-man-asking-for-the-drink-to-be-remade-card', 'DEAR MAN Asking for the Drink to Be Remade Card', 'dbt'::resource_kind, 'A DEAR MAN card for asking a barista or server to fix an order that came out wrong, for a client who would rather drink the mistake.', 'Use it to rehearse a small, scripted ask in a low-stakes setting that the client meets several times a week.', array['Adults', 'Teens']::text[], '10 minutes, then the ask', 'Drinking the wrong order in silence is a daily act of self-erasure for a socially anxious client, and the counter is a good place to practice asking. DEAR MAN (Describe, Express, Assert, Reinforce, stay Mindful, Appear confident, Negotiate) compresses here into two sentences: this is a latte and I ordered a cappuccino; could you remake it, thanks so much. The card writes the lines, rehearses them, and plans the next order where the client will ask if something is wrong. It also logs what the server actually did, which is almost always to fix it without a flicker.', '[{"id": "f0", "type": "textarea", "label": "The last time an order was wrong and I said nothing: what I drank, and how it felt:"}, {"id": "f1", "type": "textarea", "label": "Describe and Assert: my two sentences, in words that sound like me:"}, {"id": "f2", "type": "textarea", "label": "Appear confident: what my voice, eyes and shoulders will do while I say them:"}, {"id": "f3", "type": "textarea", "label": "What I predict the server will do or think:"}, {"id": "f4", "type": "textarea", "label": "What actually happened when I asked:"}, {"id": "f5", "type": "textarea", "label": "The next small ask I could make with the same two sentences:"}]'::jsonb, array['social anxiety', 'DEAR MAN', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('conversation-ping-pong-keep-the-ball-up-game', 'Conversation Ping-Pong Keep the Ball Up Game', 'game'::resource_kind, 'A paired game where two players keep a conversation going like a ping-pong rally, scoring each return and losing the point on a dead end.', 'Use it to make the mechanics of keeping a conversation alive visible and playful for people who freeze mid-exchange.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Rules: pairs sit facing each other with a referee. The referee gives a serve (a simple opener, like how was your weekend). Each reply is a return and scores a point only if it gives the other player something to hit back: a question, a detail, an opinion. A one-word answer or a silence over three seconds drops the ball and ends the rally. Rallies are counted; pairs try to beat their own record, then swap. Everyone plays three rallies. Debrief: which returns kept the ball up, what a dropped ball felt like in the body, and which return the players will try in a real conversation this week.', '[{"id": "f0", "type": "textarea", "label": "My longest rally, and who I played it with:"}, {"id": "f1", "type": "textarea", "label": "The return that kept the ball up most often (a question, a detail, an opinion):"}, {"id": "f2", "type": "textarea", "label": "What a dropped ball felt like, and how quickly the next serve made it fine:"}, {"id": "f3", "type": "textarea", "label": "A return I heard from someone else that I want to steal:"}, {"id": "f4", "type": "textarea", "label": "The conversation this week where I will try to keep the ball up for three more returns:"}]'::jsonb, array['social anxiety', 'group game', 'social skills']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('pet-loss-first-week-steps-sheet', 'Pet Loss First Week Steps Sheet', 'worksheet'::resource_kind, 'A steps sheet for the first week after a pet dies: the bowl, the leash, the walk time, and who to tell.', 'Use it to help a client through the first week of a loss that others may not take seriously, one small decision at a time.', array['Adults', 'Teens']::text[], '20 minutes, used over a week', 'The death of a pet leaves a house full of objects and a day full of habits with nowhere to go, and a client often gets little room from others to grieve it. The sheet walks the first week: what to do with the bowl and bed this week (not forever), what to do at the usual walk or feeding time, who to tell and in what words, and what to say to the person who says it was just a cat. It gives one line a day for what the client misses. Keep the pace theirs; some clients want the bowl gone today and some cannot touch it for a month.', '[{"id": "f0", "type": "textarea", "label": "What I will do with the bowl, bed and leash this week, knowing I can change my mind later:"}, {"id": "f1", "type": "textarea", "label": "The times of day that are hardest now (the walk, the feeding, coming home), and what I will do at each:"}, {"id": "f2", "type": "textarea", "label": "Who I will tell, and the words I will use:"}, {"id": "f3", "type": "textarea", "label": "What I will say to anyone who tells me it was just a pet:"}, {"id": "f4", "type": "textarea", "label": "One line a day for what I miss, seven lines:"}, {"id": "f5", "type": "textarea", "label": "At the end of the week: what helped, and what I am not ready for yet:"}]'::jsonb, array['grief and loss', 'pacing', 'routine']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('laughing-at-the-funeral-reception-guilt-thought-record', 'Laughing at the Funeral Reception Guilt Thought Record', 'cbt'::resource_kind, 'A thought record for the guilt that follows a laugh at a wake, reception or memorial gathering.', 'Use it to test the belief that laughter at a gathering of mourners means the client did not love the person enough.', array['Adults', 'Teens']::text[], '15 minutes', 'Someone tells a story at the reception, the room laughs, and the client spends the next week ashamed of having joined in. The record writes the moment, the thought (I laughed so I cannot have loved them, people will think I do not care), the belief and the guilt. Then it asks what the laughter was about, who else laughed, what the person who died would have made of the story, and what the client thinks of others who laughed. The rewrite usually finds that the laugh was grief too. Use it gently; the guilt is a form of loyalty.', '[{"id": "f0", "type": "textarea", "label": "The moment: who was telling the story, and what the room did:"}, {"id": "f1", "type": "textarea", "label": "The thought that followed, and how much I believed it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The guilt, how strong, and how long it stayed:"}, {"id": "f3", "type": "textarea", "label": "What the laughter was actually about, and who else was laughing:"}, {"id": "f4", "type": "textarea", "label": "What the person who died would have made of that story and that laugh:"}, {"id": "f5", "type": "textarea", "label": "A sentence about laughing and loving that fits the evidence, and how much I believe the first thought now:"}]'::jsonb, array['grief and loss', 'guilt', 'thought record']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('grief-as-a-second-language-i-am-learning-page', 'Grief as a Second Language I Am Learning Page', 'act'::resource_kind, 'An acceptance page that frames living after a loss as learning a second language: slow, clumsy, and spoken anyway.', 'Use it to help a client make room for being bad at grieving, and keep showing up to a life they are learning to speak.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients expect to grieve well and are ashamed when they do not: wrong words at the memorial, blankness when they should cry, tears in the hardware store. The page offers the picture of a second language. No one is fluent at first; you point, you mispronounce, you are exhausted by small conversations, and you speak anyway because the place you live now speaks this language. The client writes the words they are still learning, the conversations they avoid, and one exchange they will attempt this week in clumsy grief. Fluency is not the goal. Speaking is.', '[{"id": "f0", "type": "textarea", "label": "The ways I feel I am grieving wrong, in my own words:"}, {"id": "f1", "type": "textarea", "label": "The words in this new language I do not have yet (what to say when asked, what to call this day):"}, {"id": "f2", "type": "textarea", "label": "The conversations I avoid because my grief is clumsy in them:"}, {"id": "f3", "type": "textarea", "label": "One exchange I will attempt this week, pointing and mispronouncing if I have to:"}, {"id": "f4", "type": "textarea", "label": "What the people who already speak this language have told me about the early months:"}, {"id": "f5", "type": "textarea", "label": "What I notice about my fluency after a week of speaking anyway:"}]'::jsonb, array['grief and loss', 'acceptance', 'metaphor']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-of-the-unsaid-goodbye-card', 'Radical Acceptance of the Unsaid Goodbye Card', 'dbt'::resource_kind, 'A radical acceptance card for a death that came without the chance to say goodbye, and the mind''s refusal to let that be true.', 'Use it to help a client turn the mind, again and again, toward the fact of the missed goodbye without approving of it.', array['Adults']::text[], '20 minutes, in session first', 'A sudden death, a missed phone call, a hospital rule that kept the client out: the goodbye that did not happen is often the piece of the loss the mind fights hardest. Radical acceptance here does not mean it was okay. It means the client stops arguing with the fact. The card walks the steps: observe the fighting (if only I had called), remind that the fact cannot be changed, notice the body as it turns toward the fact, and allow the grief that fighting was holding off. Turning the mind is repeated as often as needed. Say the goodbye in session if the client wants to; the card leaves room.', '[{"id": "f0", "type": "textarea", "label": "The fact I keep fighting, in one plain sentence:"}, {"id": "f1", "type": "textarea", "label": "The if-onlys my mind runs, written out once so I can see them:"}, {"id": "f2", "type": "textarea", "label": "What fighting the fact costs me, and what it has protected me from feeling:"}, {"id": "f3", "type": "textarea", "label": "The sentence I will use to turn my mind toward the fact, each time it turns away:"}, {"id": "f4", "type": "textarea", "label": "What my body did the first time I turned toward it in session:"}, {"id": "f5", "type": "textarea", "label": "If I want to: the goodbye I would have said, in a few lines, kept here:"}]'::jsonb, array['grief and loss', 'radical acceptance', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('memory-bingo-shared-stories-game', 'Memory Bingo Shared Stories Game', 'game'::resource_kind, 'A bingo game for a grief group or a grieving family where the squares are kinds of memories and a story is told to mark each one.', 'Use it to get memories spoken aloud in a group with a light structure that gives each person turns and permission to pass.', array['Teens', 'Adults', 'Groups']::text[], '40 minutes', 'Rules: each player gets a card of memory squares (a time they made you laugh, a meal they cooked, something they always said, a trip, a habit that annoyed you, a gift). Players take turns telling a short story that fits a square; the storyteller marks it, and anyone else whose card has the same square may mark it too. A player may pass without explanation. First full row calls bingo and the game continues until time is up; the stories matter more than the win. Debrief: which square was hardest to fill, which story surprised the group, and what it was like to say the name aloud so often.', '[{"id": "f0", "type": "textarea", "label": "The squares I filled, and the story I told for each:"}, {"id": "f1", "type": "textarea", "label": "The square I passed on, and whether I want to fill it another time:"}, {"id": "f2", "type": "textarea", "label": "A story someone else told that gave me a memory I had forgotten:"}, {"id": "f3", "type": "textarea", "label": "What it was like to hear and say their name so many times in one hour:"}, {"id": "f4", "type": "textarea", "label": "One memory I will tell someone outside the group this week:"}]'::jsonb, array['grief and loss', 'group game', 'memory']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('unequal-effort-friendship-ledger-check-sheet', 'Unequal Effort Friendship Ledger Check Sheet', 'worksheet'::resource_kind, 'A ledger check for the friendship the client feels they carry, counting the actual exchanges before deciding what to do.', 'Use it to replace a vague sense of being the one who always reaches out with a plain record, then a chosen step.', array['Adults', 'Teens']::text[], 'Two weeks', 'The feeling of carrying a friendship is common and often half right. The sheet asks the client to keep a two-week ledger of who initiated, who followed up, who canceled and who showed up, with no judgment in the margins. Then they read it: is the imbalance real, is it seasonal (a friend in a hard stretch), and what does the client actually want (more from the friend, less investment, a conversation, letting it drift). The last lines plan one step. Guard against scorekeeping as a way of life; the ledger is a two-week instrument, not a habit.', '[{"id": "f0", "type": "textarea", "label": "The friendship, and what I believe about who carries it:"}, {"id": "f1", "type": "textarea", "label": "Two weeks of ledger: who reached out, who replied, who canceled, who showed up:"}, {"id": "f2", "type": "textarea", "label": "Reading the ledger: is the imbalance real, and could there be a reason on their side right now:"}, {"id": "f3", "type": "textarea", "label": "What I actually want from this friendship, in one sentence:"}, {"id": "f4", "type": "textarea", "label": "The step I am choosing: say something, do less, let it drift, or keep going as is, and why:"}, {"id": "f5", "type": "textarea", "label": "If I am saying something: my opening two lines:"}]'::jsonb, array['relationship issues', 'friendship', 'decisions']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('if-they-loved-me-they-would-just-know-thought-record', 'If They Loved Me They Would Just Know Thought Record', 'cbt'::resource_kind, 'A thought record for the rule that a partner or friend who really cared would know what the client needs without being told.', 'Use it to examine the mind-reading expectation and to practice the plain request it replaces.', array['Adults', 'Teens']::text[], '20 minutes', 'The rule that love means knowing without asking generates a steady supply of hurt: the partner did not notice, so the partner does not care. The record writes a recent instance, the thought, the belief, the feeling, and then tests the rule: times the client did not know what someone close needed, whether they loved that person less for it, what the other person was dealing with that day. Then the client drafts the plain request they did not make. Rehearse the request out loud; it is often harder to say than the client expects.', '[{"id": "f0", "type": "textarea", "label": "What happened: what I needed, and what they did or did not do:"}, {"id": "f1", "type": "textarea", "label": "The thought (if they loved me they would have…), and how much I believed it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The feeling it produced, and how I behaved afterward:"}, {"id": "f3", "type": "textarea", "label": "A time I did not know what someone I love needed, and what that said about my love:"}, {"id": "f4", "type": "textarea", "label": "What they were likely dealing with that day, honestly:"}, {"id": "f5", "type": "textarea", "label": "The plain request I could have made, in one sentence, and how much I believe the first thought now:"}]'::jsonb, array['relationship issues', 'mind reading', 'needs']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('rebuilding-trust-as-bricks-not-a-switch-page', 'Rebuilding Trust as Bricks Not a Switch Page', 'act'::resource_kind, 'A committed action page for rebuilding trust after a breach, laying one small brick at a time instead of waiting for a switch to flip.', 'Use it to help a client, on either side of a breach, choose the small acts that build trust rather than demanding or promising it whole.', array['Adults', 'Couples']::text[], '20 minutes', 'After a breach of trust, both people want a switch: the one who was hurt wants to feel safe again, the one who hurt them wants to be believed. Neither arrives on demand. The page offers bricks. The client names the trust that was broken, what a single brick looks like from their side (a kept small promise, an unprompted update, a question answered without defense), and how many bricks a week they are willing to lay or to receive. It also names what knocks bricks down. For a couple, each partner fills in their own copy and compares.', '[{"id": "f0", "type": "textarea", "label": "The trust that was broken, in one sentence, from my side:"}, {"id": "f1", "type": "textarea", "label": "The switch I keep wishing for, and what waiting for it costs:"}, {"id": "f2", "type": "textarea", "label": "What one brick looks like from where I stand (something small, repeatable, visible):"}, {"id": "f3", "type": "textarea", "label": "The bricks I am willing to lay or receive this week, and when:"}, {"id": "f4", "type": "textarea", "label": "What knocks bricks down for me, so the other person knows:"}, {"id": "f5", "type": "textarea", "label": "After a week: the bricks laid, and what the wall looks like so far:"}]'::jsonb, array['relationship issues', 'trust', 'committed action']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('validation-when-my-partner-vents-about-their-boss-card', 'Validation When My Partner Vents About Their Boss Card', 'dbt'::resource_kind, 'A validation card for the evening vent about a partner''s boss, for the client who jumps to advice or defense of the boss.', 'Use it to give a client the validation moves that let a partner feel heard before anything else is said.', array['Adults', 'Couples']::text[], '10 minutes, then the next vent', 'The nightly boss vent is where good intentions go wrong: the client offers solutions, points out the boss''s side, or checks their phone, and the partner feels alone. The card walks the DBT validation levels for that ten minutes: full attention (phone down, body turned), reflecting back what was said, naming what was not said (you felt dismissed), making sense of it given the week, and treating the reaction as reasonable. Advice waits until it is asked for. The log records the next three vents and what the partner did afterward.', '[{"id": "f0", "type": "textarea", "label": "What I usually do when my partner vents about work, honestly:"}, {"id": "f1", "type": "textarea", "label": "Full attention: what my body and phone will do for the first five minutes:"}, {"id": "f2", "type": "textarea", "label": "Reflecting back: the line I will use to say what I heard:"}, {"id": "f3", "type": "textarea", "label": "Naming what was not said: the feeling under the story, in one line:"}, {"id": "f4", "type": "textarea", "label": "The next three vents: what I did, and what my partner did in the ten minutes after:"}, {"id": "f5", "type": "textarea", "label": "When advice might fit, and how I will check whether it is wanted:"}]'::jsonb, array['relationship issues', 'validation', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('interrupting-each-other-talking-stick-agreement-for-partners', 'Interrupting Each Other Talking Stick Agreement for Partners', 'couples'::resource_kind, 'An agreement for partners who talk over each other, using an object passed between them to mark whose turn it is.', 'Use it to slow a couple''s hard conversations down to one speaker at a time, with both partners agreeing to the rules.', array['Couples']::text[], '20 minutes to set up, used in hard talks', 'When both partners interrupt, neither finishes a thought and both leave convinced they were not heard. The talking stick is simple: whoever holds the object speaks, the other listens, and the object is handed over on request, not grabbed. The sheet has each partner describe what interrupting is like from their side (urgency, fear of forgetting, feeling steamrolled), agree on the object and the rules (a time limit per turn, a way to ask for it, what happens on a slip), and pick one hard topic to try it on. Debrief after the first use, with the stick.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what happens for me when I interrupt, and what it is like when I am interrupted:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what happens for me when I interrupt, and what it is like when I am interrupted:"}, {"id": "f2", "type": "textarea", "label": "Our object, the time limit per turn, and the words for asking to hold it:"}, {"id": "f3", "type": "textarea", "label": "What we do when one of us slips and talks over the other:"}, {"id": "f4", "type": "textarea", "label": "The first hard topic we will try it on, and when:"}, {"id": "f5", "type": "textarea", "label": "After the first use: what each of us heard that we would have missed:"}]'::jsonb, array['relationship issues', 'communication', 'listening']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('choosing-a-new-doctor-safety-and-comfort-sheet', 'Choosing a New Doctor Safety and Comfort Sheet', 'worksheet'::resource_kind, 'A sheet for a survivor choosing a new doctor or dentist: what they need to feel safe, what to ask, and what to bring.', 'Use it to put a client in charge of a medical relationship from the first phone call, with their needs written before the visit.', array['Adults', 'Teens']::text[], '30 minutes', 'Medical care is often avoided by survivors because the exam room repeats too much: lying down, being touched, not being asked. The sheet puts the client in the chooser''s seat. It lists what they need (a provider of a particular gender, the option to stay dressed for the first conversation, a support person in the room, being told before each touch), the questions to ask the front desk before booking, and what to bring. It also drafts the one sentence the client can say at the start of the visit without any history: I need to be told before I am touched. Nothing on it asks what happened.', '[{"id": "f0", "type": "textarea", "label": "What I need from a provider to feel safe enough (gender, pace, a support person, being told before each touch):"}, {"id": "f1", "type": "textarea", "label": "The questions I will ask the front desk before I book:"}, {"id": "f2", "type": "textarea", "label": "The one sentence I will say at the start of the visit, with no history attached:"}, {"id": "f3", "type": "textarea", "label": "Who I will bring, and what I want them to do and not do in the room:"}, {"id": "f4", "type": "textarea", "label": "What I will do for myself in the hour after the visit, whatever happened:"}, {"id": "f5", "type": "textarea", "label": "After the first visit: what worked, what I will ask for differently, and whether I will go back:"}]'::jsonb, array['sexual abuse', 'safety', 'stabilizing']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('i-should-have-known-better-gentle-hindsight-check-sheet', 'I Should Have Known Better Gentle Hindsight Check Sheet', 'cbt'::resource_kind, 'A gentle hindsight check for the survivor''s belief that they should have seen it coming, done in session with the facts they had then.', 'Use it to separate what the client knows now from what they could have known then, without asking for the story.', array['Adults']::text[], '25 minutes, in session only', 'I should have known is self-blame that borrows today''s knowledge to judge yesterday''s decisions. The sheet separates them carefully: what the client knows now, what they actually knew at the time, what anyone with only that information would reasonably have done, and who taught them that they should have seen it. It stays at the level of knowledge and judgment, never events; the client writes only what they knew, not what happened. Complete it in session, watch arousal, and stop if the client begins to recount. The last line is a sentence about a person who did not have the information.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my own words (I should have known…), and how much I believe it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "What I know now that I did not know then, in general terms:"}, {"id": "f2", "type": "textarea", "label": "What I actually knew at the time, in general terms, without the details of what happened:"}, {"id": "f3", "type": "textarea", "label": "What a reasonable person with only that information would have done:"}, {"id": "f4", "type": "textarea", "label": "Where I learned that I should have seen it coming, and whose voice says it:"}, {"id": "f5", "type": "textarea", "label": "A sentence about a person who did not have the information, and how much I believe the first belief now:"}]'::jsonb, array['sexual abuse', 'self-blame', 'stabilizing']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('telling-only-the-chapters-i-choose-page', 'Telling Only the Chapters I Choose Page', 'act'::resource_kind, 'A values page about disclosure: which parts of the story the client shares, with whom, and the right to leave chapters closed.', 'Use it to help a survivor decide on their own terms what to tell a partner, a friend or a provider, and what to keep.', array['Adults', 'Teens']::text[], '20 minutes', 'Survivors often feel they owe people the whole story or none of it, and both leave them without control. The page frames their history as a book whose chapters they own. For each person in their life they might tell, the client decides which chapters, if any, that person needs for the relationship the client wants with them, and which stay closed. It also plans the sentence for closing a chapter when someone asks for more. The page never asks what is in the chapters; the client writes titles only, or nothing. Choosing not to tell is as valid as choosing to tell.', '[{"id": "f0", "type": "textarea", "label": "The people I am considering telling something to, and the relationship I want with each:"}, {"id": "f1", "type": "textarea", "label": "For each: the chapter titles, if any, that relationship actually needs (titles only, no contents):"}, {"id": "f2", "type": "textarea", "label": "The chapters that stay closed for now, and my reasons, which I do not owe anyone:"}, {"id": "f3", "type": "textarea", "label": "The sentence I will use to close a chapter when someone asks for more:"}, {"id": "f4", "type": "textarea", "label": "The value that guides what I tell and what I keep:"}, {"id": "f5", "type": "textarea", "label": "After a conversation: what I told, what I kept, and how it felt to be the one who chose:"}]'::jsonb, array['sexual abuse', 'values', 'boundaries']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('observe-the-breath-return-after-a-startle-card', 'Observe the Breath Return After a Startle Card', 'dbt'::resource_kind, 'An observe card for the minute after a startle, watching the breath come back on its own without forcing it.', 'Use it to give a survivor a small practice that proves the body settles itself, and a log that shows it over a week.', array['Adults', 'Teens']::text[], 'Two minutes, as needed', 'A startle sends the breath high and fast, and the client often tries to seize control of it, which adds a struggle to the alarm. The card asks for observation instead: after a startle, notice the breath without changing it, count how many breaths until it slows on its own, feel the feet, and record. Over a week the client sees the return happen every time, which builds trust in the body''s settling. Practice once in session with a mild startle the client chooses, such as a dropped book. The card never asks what the startle reminded them of.', '[{"id": "f0", "type": "textarea", "label": "In session, with a startle I chose: how many breaths until it slowed on its own:"}, {"id": "f1", "type": "textarea", "label": "Each startle this week: where I was, and how many breaths until the slowing (no details of the cue needed):"}, {"id": "f2", "type": "textarea", "label": "What I noticed about the breath while I only watched it:"}, {"id": "f3", "type": "textarea", "label": "What my feet felt like on the floor as the breath came back:"}, {"id": "f4", "type": "textarea", "label": "What the week of counting showed me about my body''s own settling:"}, {"id": "f5", "type": "textarea", "label": "What I want to say to myself the next time the breath goes high:"}]'::jsonb, array['sexual abuse', 'observe', 'grounding']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('safe-grown-ups-phone-number-bracelet-craft', 'Safe Grown-Ups Phone Number Bracelet Craft', 'kids'::resource_kind, 'A beaded bracelet the child makes with a parent, each color bead standing for a safe grown-up the child can tell anything.', 'Use it to give a child a wearable reminder of who to tell, and a parent a way to rehearse the telling without alarm.', array['Children']::text[], '30 minutes to make, revisited often', 'A child who has been hurt, or is being taught to stay safe, needs the list of safe grown-ups to be closer than a poster on a wall. The child and parent string a bracelet with one color bead per safe grown-up and practice saying each name while touching its bead. The parent rehearses with the child what they would say to that person and that the grown-up will believe them, and the child practices telling until someone listens. Make a second bracelet for the backpack. A disclosure during this craft falls under your state''s mandatory reporting duties; know your steps before you begin.', '[{"id": "f0", "type": "textarea", "label": "The safe grown-ups on my bracelet, and the color bead for each:"}, {"id": "f1", "type": "textarea", "label": "What I would say to one of them if something was wrong, practiced out loud:"}, {"id": "f2", "type": "textarea", "label": "What I know a safe grown-up does when I tell them (believes me, helps me, does not get mad at me):"}, {"id": "f3", "type": "textarea", "label": "Where I will keep my bracelet, and where the second one goes:"}, {"id": "f4", "type": "textarea", "label": "For my grown-up: how we practiced the telling calmly, and how often we will touch the beads and say the names:"}]'::jsonb, array['sexual abuse', 'kids', 'safety']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('coping-skills-car-kit-packing-sheet', 'Coping Skills Car Kit Packing Sheet', 'worksheet'::resource_kind, 'A packing sheet for a small kit kept in the car: the physical items the client''s coping skills need, chosen and stocked.', 'Use it to make the client''s skills available where they often need them most, in a parked car between places.', array['Adults', 'Teens']::text[], '20 minutes to plan, 30 to pack', 'A great many hard moments happen in a parked car: after the appointment, before the shift, in the school pickup line. The sheet matches each coping skill the client actually uses to the object it needs (a cold pack for TIPP, a scent, a stress ball, a playlist written down, a card with two phone numbers, gum, a small notebook) and plans where in the car the kit lives and when it gets restocked. Keep it to a shoebox or a glove compartment. For a client with a safety plan, the numbers card includes 988 (call or text) and a named person. Check the kit together in a month.', '[{"id": "f0", "type": "textarea", "label": "The hard moments that happen in my car, and where I am usually parked:"}, {"id": "f1", "type": "textarea", "label": "The skills I actually use, and the object each one needs:"}, {"id": "f2", "type": "textarea", "label": "The numbers card: two people, and 988 (call or text) if I ever need it:"}, {"id": "f3", "type": "textarea", "label": "Where in the car the kit lives, and what I will say to anyone who asks about it:"}, {"id": "f4", "type": "textarea", "label": "The day each month I will check and restock it:"}, {"id": "f5", "type": "textarea", "label": "The first time I used it: which item, and what happened:"}]'::jsonb, array['coping skills', 'planning', 'self-soothing']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('a-skill-that-failed-once-never-works-sheet', 'A Skill That Failed Once Never Works Sheet', 'cbt'::resource_kind, 'An overgeneralization sheet for the client who tries a coping skill in one hard moment, finds it does not help, and drops it for good.', 'Use it to test a one-trial verdict on a skill against the conditions it was tried in and what it might do elsewhere.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients discard skills the way they discard umbrellas that failed in a hurricane. The sheet takes one dropped skill and asks: when it was tried, how intense the moment was, how many times it had been practiced before that, and what the client expected it to do. Then it asks what the skill might do in a smaller moment and whether the client is willing to run two more trials at a lower intensity. The rule being tested is written at the top: if it did not work once, it never will. Most clients can see the rule once it is written.', '[{"id": "f0", "type": "textarea", "label": "The skill I dropped, and the moment I tried it (how intense, 0 to 10):"}, {"id": "f1", "type": "textarea", "label": "How many times I had practiced it before that moment:"}, {"id": "f2", "type": "textarea", "label": "What I expected it to do, and what it actually did:"}, {"id": "f3", "type": "textarea", "label": "The rule I applied afterward, written as a sentence:"}, {"id": "f4", "type": "textarea", "label": "Two smaller moments this week where I will try it again, and what a fair test would look like:"}, {"id": "f5", "type": "textarea", "label": "After the two trials: what the skill did, and what I think of the rule now:"}]'::jsonb, array['coping skills', 'overgeneralization', 'behavioral experiment']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('coping-skill-that-makes-room-versus-one-that-fights-page', 'Coping Skill That Makes Room Versus One That Fights Page', 'act'::resource_kind, 'A sorting page that separates the client''s coping skills into those that make room for a feeling and those that fight it.', 'Use it to help a client notice when a skill has become a way of getting rid of a feeling, and choose some that let it be there.', array['Adults', 'Teens']::text[], '20 minutes', 'The same skill can be used two ways: a breath that makes room for anxiety and a breath that is meant to make it leave. The page lists the client''s skills and asks, for each, what the client is hoping it will do and what happens when the feeling stays anyway. Skills used to fight tend to leave the client worse when they do not win. The client marks each as room or fight in its usual use, picks two room skills to lean on this week, and writes what making room would sound like in their own head. Both kinds have a place; the page just makes the difference visible.', '[{"id": "f0", "type": "textarea", "label": "My skills, listed, with what I am hoping each one will do:"}, {"id": "f1", "type": "textarea", "label": "For each: what happens when I use it and the feeling stays:"}, {"id": "f2", "type": "textarea", "label": "Which ones I mostly use to fight the feeling, and which ones make room for it:"}, {"id": "f3", "type": "textarea", "label": "Two room skills I will lean on this week, and the moments I will use them:"}, {"id": "f4", "type": "textarea", "label": "What making room sounds like in my own head, in a sentence:"}, {"id": "f5", "type": "textarea", "label": "After a week: what changed when I stopped asking the skill to win:"}]'::jsonb, array['coping skills', 'acceptance', 'willingness']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('improve-the-moment-one-thing-in-the-moment-card', 'IMPROVE the Moment One Thing in the Moment Card', 'dbt'::resource_kind, 'An IMPROVE card for the one thing in the moment skill: putting all attention on a single present task while a hard hour passes.', 'Use it to give a client one narrow, doable focus for a hard hour so the hour is spent doing rather than enduring.', array['Adults', 'Teens']::text[], 'Fifteen minutes to an hour, as needed', 'One thing in the moment is the plainest piece of IMPROVE and often the most useful: when a hard hour arrives, pick one task and give it everything. The card asks the client to list the small tasks that could hold full attention (washing one window, grating cheese, sorting a drawer, copying a recipe by hand), to pick one when the hour comes, and to return attention to it each time the mind leaves. The log records the hour: the task, how many returns, how the hour felt compared with the usual enduring. No task is too small; the point is the narrowing.', '[{"id": "f0", "type": "textarea", "label": "Five small tasks that could hold my full attention for a hard hour:"}, {"id": "f1", "type": "textarea", "label": "The hard hour this week: when it came, and the task I picked:"}, {"id": "f2", "type": "textarea", "label": "How many times my attention left, and how I brought it back each time:"}, {"id": "f3", "type": "textarea", "label": "How the hour felt compared with how I usually spend a hard hour:"}, {"id": "f4", "type": "textarea", "label": "What the task looked like when I was done, and what that was like to see:"}, {"id": "f5", "type": "textarea", "label": "The task I will reach for first next time:"}]'::jsonb, array['coping skills', 'IMPROVE', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('coping-skill-auction-bid-your-chips-game', 'Coping Skill Auction Bid Your Chips Game', 'game'::resource_kind, 'An auction game where players bid poker chips on coping skills for described situations, then defend their winning bids to the group.', 'Use it to get a group weighing which skill fits which moment, with turns, stakes and a debrief on why they spent their chips.', array['Teens', 'Adults', 'Groups']::text[], '35 minutes', 'Rules: each player gets twenty chips. The auctioneer reads a situation (the text that ruins your morning, a panic surge in a store, the urge after a fight) and then offers coping skills one by one from a stack of cards. Players bid chips on the skills they would most want for that situation; the highest bidder wins the card and must say in one sentence why it fits. Play five situations; the player with the most cards the group agrees fit wins. Debrief: which skills everyone fought over, which went unbid, and whether players spent chips on skills they actually use or ones they wish they did.', '[{"id": "f0", "type": "textarea", "label": "The skills I won, and the situations I bid on them for:"}, {"id": "f1", "type": "textarea", "label": "The skill I overpaid for, and why I wanted it so badly:"}, {"id": "f2", "type": "textarea", "label": "A skill nobody bid on, and whether it deserved better:"}, {"id": "f3", "type": "textarea", "label": "Whether I bid on skills I actually use or skills I wish I used:"}, {"id": "f4", "type": "textarea", "label": "One skill I won in the auction that I will try in a real moment this week:"}]'::jsonb, array['coping skills', 'group game', 'decisions']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('elevator-ride-floor-by-floor-step-plan-sheet', 'Elevator Ride Floor by Floor Step Plan Sheet', 'worksheet'::resource_kind, 'A step plan that builds from standing in the lobby to riding an elevator alone to the top floor, with a record for each step.', 'Use it to give a client a graded sequence for elevator fear with a clear stopping place at each step and nothing skipped.', array['Adults', 'Teens']::text[], 'Several sessions over a few weeks', 'Elevator fear closes off whole buildings and is unusually well suited to a graded plan because the steps are built into the machine. The sheet lays them out: watching the doors from the lobby, standing inside with the doors open, one floor with a companion, one floor alone, three floors, a full ride, a ride during a busy hour. The client predicts the fear for each step, does it, records the actual peak and how long it took to come down, and repeats a step until it is boring before moving on. Stairs remain allowed between practices; the plan asks only for the planned rides.', '[{"id": "f0", "type": "textarea", "label": "My steps, from the lobby to the busy-hour full ride, in order:"}, {"id": "f1", "type": "textarea", "label": "For each step before I do it: my predicted peak fear (0 to 10) and what I think will happen:"}, {"id": "f2", "type": "textarea", "label": "For each step after: the actual peak, how long it took to come down, and what happened:"}, {"id": "f3", "type": "textarea", "label": "The step I repeated the most times before it got boring:"}, {"id": "f4", "type": "textarea", "label": "What I did with my attention during the rides (counting floors, a breath, watching the numbers):"}, {"id": "f5", "type": "textarea", "label": "The building I have been avoiding that I will now go into, and when:"}]'::jsonb, array['phobias', 'hierarchy', 'exposure']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('getting-sick-in-public-prediction-sheet', 'Getting Sick in Public Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the fear of vomiting in public, testing what the client expects would happen against what they know of others.', 'Use it to put the predicted catastrophe of being sick in public beside the actual record of what happens when people are.', array['Adults', 'Teens']::text[], '20 minutes', 'Fear of being sick in public shapes where a client eats, travels and sits, and the prediction behind it is rarely examined: that it would be catastrophic, permanent and witnessed by everyone. The sheet writes the prediction in detail (who would see, what they would do, how long it would be remembered), the odds the client gives it, and then the evidence: times they have seen someone be sick in public, what they did and thought, how long they remembered it. Then a smaller test: the restaurant seat the client avoids, taken for one meal. This sheet stays with predictions and induces nothing.', '[{"id": "f0", "type": "textarea", "label": "The prediction, in detail: where, who would see, what they would do, how long it would be remembered:"}, {"id": "f1", "type": "textarea", "label": "The odds I give it on a normal day out (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "Times I have seen someone unwell in public: what I did, what I thought, how long I remembered it:"}, {"id": "f3", "type": "textarea", "label": "What the people around me would most likely actually do, based on that:"}, {"id": "f4", "type": "textarea", "label": "The seat, meal or trip I avoid because of the prediction, and the one I will take this week:"}, {"id": "f5", "type": "textarea", "label": "After: what happened, and how the prediction looks now:"}]'::jsonb, array['phobias', 'predictions', 'avoidance']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('making-room-for-the-shake-on-the-ladder-page', 'Making Room for the Shake on the Ladder Page', 'act'::resource_kind, 'A willingness page for fear of heights at the household scale: a stepladder, a stool, a balcony, with the shake brought along.', 'Use it to help a client do the small high things their life needs while their legs shake, rather than waiting for steady legs.', array['Adults']::text[], '15 minutes, then the climb', 'Fear of heights is not only cliffs; it is the lightbulb the client has not changed, the gutter never cleared, the hotel balcony never stepped onto. The page asks what high things the client''s life actually needs, what the shake says (you will fall, your legs will give out), and what they are willing to feel to change the bulb. Then the climb: a stepladder, two rungs, standing there for one minute with the shake allowed to be there. The page logs what the legs did and whether the client stayed. Steadiness is not required. Doing the thing with the shake is the practice.', '[{"id": "f0", "type": "textarea", "label": "The small high things my life needs that I have been leaving undone:"}, {"id": "f1", "type": "textarea", "label": "What the shake says will happen on the ladder, in its own words:"}, {"id": "f2", "type": "textarea", "label": "What I am willing to feel in order to change the bulb or step onto the balcony:"}, {"id": "f3", "type": "textarea", "label": "The climb: how high, how long I stayed, and what my legs did:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the shake once I stopped waiting for it to leave:"}, {"id": "f5", "type": "textarea", "label": "The next small high thing, and when:"}]'::jsonb, array['phobias', 'willingness', 'acceptance']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('cope-ahead-imagery-for-the-flight-takeoff-card', 'Cope Ahead Imagery for the Flight Takeoff Card', 'dbt'::resource_kind, 'A cope ahead card that rehearses the takeoff minute by minute in imagination, with a skill assigned to each sensation.', 'Use it to let a fearful flyer practice the hardest two minutes of a flight many times before boarding.', array['Adults', 'Teens']::text[], '20 minutes, repeated before the trip', 'Takeoff is where most flying fear peaks, and it lasts about two minutes. Cope ahead rehearses exactly those minutes: the engines, the push, the wheels leaving, the climb, the bump as the flaps retract, the ding of the seatbelt sign. For each the client writes the sensation they expect and the skill they will use (a paced breath, feet pressed to the floor, a hand on the armrest held lightly, a sentence about turbulence being normal). Then they imagine the whole sequence slowly, three times, before the flight. Afterward the log records which moments matched and which skill they actually used.', '[{"id": "f0", "type": "textarea", "label": "The flight, and the moment of takeoff I dread most:"}, {"id": "f1", "type": "textarea", "label": "The sequence of takeoff as I expect it, from engines to the seatbelt ding:"}, {"id": "f2", "type": "textarea", "label": "For each moment: the sensation I expect, and the skill I will use:"}, {"id": "f3", "type": "textarea", "label": "The rehearsal: how many times I imagined it through, and how it felt the third time compared with the first:"}, {"id": "f4", "type": "textarea", "label": "On the flight: which moments matched, and which skill I actually used:"}, {"id": "f5", "type": "textarea", "label": "What I will rehearse differently for the return flight:"}]'::jsonb, array['phobias', 'cope ahead', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('scary-thing-shrink-glasses-craft', 'Scary Thing Shrink Glasses Craft', 'kids'::resource_kind, 'Paper glasses the child decorates with a parent and puts on to look at a drawing of a feared thing, drawn smaller each time.', 'Use it to give a child a playful ritual for approaching a feared object in pictures, with the parent making the glasses magic.', array['Children']::text[], '40 minutes to make, then short practices', 'A child with a specific fear (dogs, bugs, the vacuum, the dark basement) can begin approaching it through pictures long before the real thing, and a pair of shrink glasses makes it a game. The child and parent cut and decorate cardboard glasses. The child draws the scary thing big, puts on the glasses, looks at it for a count of ten, and then draws it a little smaller on the next page. Repeat over days; the parent holds the pages, does the counting, and never rushes to the real thing. When the drawing is small, the parent and child plan one real-life look from far away, glasses on.', '[{"id": "f0", "type": "textarea", "label": "The scary thing I drew, and how big it was on the first page:"}, {"id": "f1", "type": "textarea", "label": "What my shrink glasses look like, and what makes them magic:"}, {"id": "f2", "type": "textarea", "label": "How long I looked at the drawing with the glasses on, and what my body did:"}, {"id": "f3", "type": "textarea", "label": "How small the scary thing is now, after several drawings:"}, {"id": "f4", "type": "textarea", "label": "For my grown-up: how I kept the pace slow, and the far-away real-life look we are planning together:"}]'::jsonb, array['phobias', 'kids', 'drawing']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('haircut-appointment-without-the-spiral-plan-sheet', 'Haircut Appointment Without the Spiral Plan Sheet', 'worksheet'::resource_kind, 'A plan for the salon or barber chair, where the mirror, the cape and the small talk set off a spiral for the client.', 'Use it to help a client get through a routine appointment they avoid or dread, with the hard moments planned for.', array['Adults', 'Teens']::text[], '20 minutes before, 10 after', 'The salon chair is an hour of forced mirror time with a stranger''s hands near the face, and clients with a harsh view of their appearance often avoid it for months or endure it in silence. The sheet plans the hour: how to describe the cut without a verdict on their face, where to look while the mirror is in front of them (the stylist''s hands, the window, the phone), what to say to the stylist''s small talk, and the comment the client will not accept from themselves on the way out. Afterward they record what the spiral did and what they wore to leave.', '[{"id": "f0", "type": "textarea", "label": "How long since my last cut, and what I usually tell myself about why I have put it off:"}, {"id": "f1", "type": "textarea", "label": "How I will describe what I want, in words about the hair and not about my face:"}, {"id": "f2", "type": "textarea", "label": "Where I will look during the hour, and what I will do with my hands:"}, {"id": "f3", "type": "textarea", "label": "What I will say when the stylist asks a question about the cut or about my life:"}, {"id": "f4", "type": "textarea", "label": "The comment I will not make to myself on the way out, and what I will say instead:"}, {"id": "f5", "type": "textarea", "label": "After: what the spiral did, how long it lasted, and what I will do differently next time:"}]'::jsonb, array['body image', 'avoidance', 'planning']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('they-zoomed-in-on-the-photo-thought-record', 'They Zoomed In on the Photo Thought Record', 'cbt'::resource_kind, 'A thought record for the certainty that someone who saw the client''s photo zoomed in on the part they hate most.', 'Use it to examine a mind-reading thought about appearance and look at what people actually do with photos.', array['Adults', 'Teens']::text[], '15 minutes', 'A photo goes out and the client knows exactly which part of it everyone enlarged. The record writes the moment, the thought (they zoomed in on my chin, they are showing it to someone), how strongly the client believed it and the feeling it brought. Then the evidence: what the client does with other people''s photos, how long they look, what they remember of them a day later, and what the one comment they received actually said. The rewrite finds the gap between how long the client studies their own image and how long anyone else does.', '[{"id": "f0", "type": "textarea", "label": "The photo, who saw it, and the part I am sure they zoomed in on:"}, {"id": "f1", "type": "textarea", "label": "The thought, and how much I believed it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The feeling, and what I did afterward (deleted, untagged, asked for reassurance):"}, {"id": "f3", "type": "textarea", "label": "What I do with other people''s photos: how long I look, what I notice, what I remember a day later:"}, {"id": "f4", "type": "textarea", "label": "What anyone actually said about the photo, word for word:"}, {"id": "f5", "type": "textarea", "label": "A sentence that fits the evidence, and how much I believe the first thought now:"}]'::jsonb, array['body image', 'thought record', 'mind reading']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('what-my-body-carried-me-through-today-page', 'What My Body Carried Me Through Today Page', 'act'::resource_kind, 'A values page that ends the day with what the body did and carried, rather than how it looked doing it.', 'Use it to shift a client''s nightly review of their body from appearance to function and the life it made possible.', array['Adults', 'Teens']::text[], 'Five minutes nightly for a week', 'Clients with a harsh body image review their appearance every night without choosing to. The page offers a different review: what the body carried the client through today. The stairs, the long meeting, the laugh, the hug, the walk to the car in the rain, the hard conversation it stayed in the room for. One line per thing, nothing about how any of it looked. Over a week a different picture of the body accumulates. Do not let the page become a performance log either; resting on the couch counts as carrying.', '[{"id": "f0", "type": "textarea", "label": "Tonight: what my body carried me through today, one line per thing, nothing about how it looked:"}, {"id": "f1", "type": "textarea", "label": "The thing on that list I would not have noticed without writing it:"}, {"id": "f2", "type": "textarea", "label": "What my body asked for today, and whether I gave it:"}, {"id": "f3", "type": "textarea", "label": "Seven nights, a few lines each:"}, {"id": "f4", "type": "textarea", "label": "What the week of lists says about my body that the mirror does not:"}, {"id": "f5", "type": "textarea", "label": "One way I will thank my body this week, in an action and not a word:"}]'::jsonb, array['body image', 'values', 'self-compassion']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-changing-outfits-five-times-card', 'Opposite Action to Changing Outfits Five Times Card', 'dbt'::resource_kind, 'An opposite action card for the morning outfit spiral: one choice, worn out the door, with the urge to change logged rather than obeyed.', 'Use it to help a client break the morning cycle of changing clothes to fix a feeling that clothes cannot fix.', array['Adults', 'Teens']::text[], 'Ten minutes each morning for a week', 'Changing outfits five times before leaving is a mood regulation attempt that never works and makes the client late and raw. Opposite action here: the first reasonable outfit stays on, the urge to change is written down instead of acted on, and the client walks out the door. The card asks the client to notice the feeling the changing is trying to fix, to name it, and to do the opposite of what it demands: dress once, leave on time, let the feeling ride along. Log each morning: the urge (0 to 10) at the door and an hour later. No part of the card comments on how the client looks.', '[{"id": "f0", "type": "textarea", "label": "The feeling the changing is trying to fix, named plainly:"}, {"id": "f1", "type": "textarea", "label": "The rule for the week: the first reasonable outfit stays on, and the urge gets written here, not obeyed:"}, {"id": "f2", "type": "textarea", "label": "Each morning: the urge to change at the door (0 to 10), and an hour later:"}, {"id": "f3", "type": "textarea", "label": "What my mind said on the way out, and what I did instead of turning back:"}, {"id": "f4", "type": "textarea", "label": "The morning I slipped, if I did, and what I will do the next morning:"}, {"id": "f5", "type": "textarea", "label": "End of the week: what happened to the urge, and what happened to my mornings:"}]'::jsonb, array['body image', 'opposite action', 'DBT']::text[], '2026-11-22T15:00:00+00:00'::timestamptz),
  ('gym-together-without-body-commentary-pact-for-partners', 'Gym Together Without Body Commentary Pact for Partners', 'couples'::resource_kind, 'A pact for partners who exercise together, where one partner''s comments about bodies, their own or others'', land hard on the other.', 'Use it to let a couple keep sharing a gym or a walk with an agreement about what is said about bodies while they do it.', array['Couples']::text[], '20 minutes', 'Exercising together can be good for a couple and hard for a partner with a harsh body image, because the other''s running commentary (about their own body, the client''s, or strangers'') lands with a force the commenter does not intend. The sheet has each partner say what they hear and what they mean, then agrees on the pact: what is off the table (comments on anyone''s shape, comparisons, before-and-after talk), what is welcome (effort, strength, how it felt, what to do next), and the one word either can say to flag a slip. The last line keeps the activity itself: when they will go next.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the comments that land hard on me during exercise, and what I hear in them:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I usually mean by those comments, and what I would rather say:"}, {"id": "f2", "type": "textarea", "label": "What is off the table for both of us while we exercise, in plain words:"}, {"id": "f3", "type": "textarea", "label": "What we welcome instead: effort, strength, how it felt, what to do next:"}, {"id": "f4", "type": "textarea", "label": "Our one word for flagging a slip, and what the other does when they hear it:"}, {"id": "f5", "type": "textarea", "label": "When we will go next, and what we will do together afterward:"}]'::jsonb, array['body image', 'communication', 'support']::text[], '2026-11-22T15:00:00+00:00'::timestamptz)
